/* DAWAH X — ahmad, অধ্যায় 64 · খণ্ড 64 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][64]=[[12601,12601,"","আমরা যারা আমাকে বাদ দিয়ে যেতে বলেছি, তাদের কথা বলছি, ঈশ্বর তার জন্য প্রার্থনা করেন এবং আত্মসমর্পণ করেন, কোন থ্রেড স্পর্শ করেন না,","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا شَمِمْتُ رِيحًا قَطُّ ‏ ‏مِسْكًا ‏ ‏وَلَا ‏ ‏عَنْبَرًا أَطْيَبَ مِنْ رِيحِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا مَسِسْتُ قَطُّ ‏ ‏خَزًّا ‏ ‏وَلَا حَرِيرًا أَلْيَنَ مِنْ كَفِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12602,12602,"","আমাদের কিছু লোক বলেছে যে যুদ্ধ, প্রভু, আমি খুব ভাল আছি... ...আমি এত সহজে যেতে পারব না। ( দ্বিতীয়.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏يَا رَسُولَ اللَّهِ مَا رَأَيْنَا مِثْلَ قَوْمٍ قَدِمْنَا عَلَيْهِمْ أَحْسَنَ مُوَاسَاةً فِي قَلِيلٍ وَلَا أَحْسَنَ بَذْلًا فِي كَثِيرٍ لَقَدْ كَفَوْنَا ‏ ‏الْمَئُونَةَ ‏ ‏وَأَشْرَكُونَا فِي الْمَهْنَإِ حَتَّى لَقَدْ حَسِبْنَا أَنْ يَذْهَبُوا بِالْأَجْرِ كُلِّهِ قَالَ لَا ‏ ‏مَا أَثْنَيْتُمْ عَلَيْهِمْ ‏ ‏وَدَعَوْتُمْ اللَّهَ عَزَّ وَجَلَّ لَهُمْ ‏","","",""],[12603,12603,"","আমরা হামিদের থেকে ভাল কথা বলেছি, যারা আমার বাবাকে বলেছে, আমরা আমার ছেলের সাথে কথা বলেছি, আমরা এমনকি নিরাপদও করেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তাকে দেয়া হয়েছে। আমি তোমাকে সূর্যের আনন্দ ও আনন্দ থেকে ছিনিয়ে নেব।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْجُبْنِ وَالْبُخْلِ وَفِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَعَذَابِ الْقَبْرِ ‏","","",""],[12604,12604,"","আমরা আমাদের একটি ছোট জিহ্বা আছে যাদের একটি ছেলে আছে বলে ভালো নাম বলা হয়েছে। আমরা ঈশ্বরের কাছে প্রার্থনা করেছিলাম তিনি উদ্ধার করতে এবং তিনি তাঁর মুখে হেঁটে হেঁটেছিলেন। আমরা যখন তাকে পরিবর্তন করেছিলাম, সে বলেছিল, \"বাবা, কিছু একটা করো.\"","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ابْنًا ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏صَغِيرًا كَانَ يُقَالُ لَهُ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏وَكَانَ لَهُ ‏ ‏نُغَيْرٌ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ عَلَيْهِ ضَاحَكَهُ فَرَآهُ حَزِينًا فَقَالَ مَا بَالُ ‏ ‏أَبِي عُمَيْرٍ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ مَاتَ ‏ ‏نُغَيْرُهُ ‏ ‏قَالَ فَجَعَلَ يَقُولُ ‏ ‏يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[12605,12605,"","আমরা হারুনের মধ্যে আছি... ...তাকে মারতে বলা হয়েছে, যুবকটি তাকে মারতে চায় না, নাকি দুই জন বলেছে যে সে খুব দ্রুত করে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏أَخَضَبَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَمْ ‏ ‏يَشِنْهُ ‏ ‏الشَّيْبُ قِيلَ أَوَشَيْنٌ هُوَ قَالَ كُلُّكُمْ يَكْرَهُهُ إِنَّمَا كَانَتْ شُعَيْرَاتٌ فِي مُقَدَّمِ لِحْيَتِهِ ‏","","",""],[12606,12606,"","আমরা এমন লোকদের কথা বলেছি যারা আগে ঈশ্বরকে দেখেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا قِيلَ يَا رَسُولَ اللَّهِ هَذَا نَنْصُرُهُ مَظْلُومًا فَكَيْفَ نَنْصُرُهُ ظَالِمًا قَالَ تَمْنَعُهُ مِنْ الظُّلْمِ ‏","","",""],[12607,12607,"","আমরা কথা বলার চেয়ে ভালো কথা বলেছি, ঈশ্বর তাকে শিক্ষা দিয়েছেন এবং আমার ছেলেকে উদ্ধার করেছেন। তারা বলল, একজন মানুষ কবর দেবার আগে আল্লাহ্‌কে বলে। এটা রেখে দিয়েছে আর জিজ্ঞেস করেছে, ঈশ্বর তোমাকে যেতে দিবেন না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِنَخْلٍ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فَسَمِعَ صَوْتًا فَقَالَ مَا هَذَا قَالُوا قَبْرُ رَجُلٍ دُفِنَ فِي الْجَاهِلِيَّةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[12608,12608,"","আমরা প্রভুর ভালোর জন্য একে অপরের সাথে কথা বলেছি... ...আর হরিণের মন বাঁচিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏مَمْسُوحُ الْعَيْنِ الْيُسْرَى عَلَيْهَا ‏ ‏ظَفَرَةٌ ‏ ‏مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ ‏","","",""],[12609,12609,"","আমরা ভগবানের সাথে কথা বলেছি, সে কি বলে সে কষ্ট পাচ্ছে?","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا يُقَالَ فِي الْأَرْضِ اللَّهَ اللَّهَ ‏","","",""],[12610,12610,"","আমরা তাদের কথা বলেছি যারা ঈশ্বরের কাছে আছে এবং তার মুখে তার মুখ ছিল। একজন তার অনুগ্রহ ও অনুগ্রহের মৃত্যু তার মৃত্যু। আপনি একজন মা বলেছেন যে তারা এটা করেছে এবং সে তাদের কাছে ফোন করেছে। ঈশ্বর আর আমি তোমার জন্য এটা করবো না, শেষ বরফ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شُجَّ ‏ ‏فِي وَجْهِهِ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَكُسِرَتْ ‏ ‏رَبَاعِيَتُهُ ‏ ‏وَرُمِيَ رَمْيَةً عَلَى كَتِفَيْهِ فَجَعَلَ الدَّمُ يَسِيلُ عَلَى وَجْهِهِ وَهُوَ يَمْسَحُهُ عَنْ وَجْهِهِ وَهُوَ يَقُولُ ‏ ‏كَيْفَ تُفْلِحُ أُمَّةٌ فَعَلُوا هَذَا بِنَبِيِّهِمْ وَهُوَ يَدْعُوهُمْ إِلَى اللَّهِ عَزَّ وَجَلَّ فَأَنْزَلَ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ ‏} ‏إِلَى آخِرِ ‏ ‏الْآيَةَ ‏","","",""],[12611,12611,"","আমরা যারা ঈশ্বরকে ঈশ্বরকে দান করে তাদের কথা বলছি এবং আমি এটা করতে চাই না, আমার মনে হয় শত বছর জেদের জন্ম দেবে, ঈশ্বর তাকে শিখিয়েছিলেন এবং আমাদের জনগণকে উদ্ধার করবেন। ( আদিপুস্তক ১: ২৬) কিন্তু, এই বিজয়ে বলা হয়েছিল যে, ঈর্ষার কারণে তারা আমাদের বোনের ছেলে না হওয়া পর্যন্ত, ঈশ্বরের কাছে সবচেয়ে ভালো কিছু ছিল । আর যদি আমি মানুষদের বন্ধু করি বা তাদের ইচ্ছা নিয়ে তার হাতে শ্বাস নিই, তাহলে আমি সেখান থেকে চলে যেতাম। ঠিক আছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَعْطَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غَنَائِمِ ‏ ‏حُنَيْنٍ ‏ ‏الْأَقْرَعَ بْنَ حَابِسٍ ‏ ‏مِائَةً مِنْ الْإِبِلِ ‏ ‏وَعُيَيْنَةَ بْنَ حِصْنٍ ‏ ‏مِائَةً مِنْ الْإِبِلِ فَقَالَ نَاسٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُعْطِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَائِمَنَا نَاسًا تَقْطُرُ سُيُوفُهُمْ مِنْ دِمَائِنَا ‏ ‏أَوْ تَقْطُرُ سُيُوفُنَا مِنْ دِمَائِهِمْ ‏ ‏فَبَلَغَهُ ذَلِكَ فَأَرْسَلَ إِلَى ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ هَلْ فِيكُمْ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ابْنُ أُخْتٍ لَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ أَقُلْتُمْ كَذَا وَكَذَا أَمَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا وَتَذْهَبُونَ ‏ ‏بِمُحَمَّدٍ ‏ ‏إِلَى دِيَارِكُمْ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَخَذَ النَّاسُ وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏أَخَذْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏أَوْ ‏ ‏شِعْبَهُمْ ‏ ‏الْأَنْصَارُ ‏ ‏كَرِشِي ‏ ‏وَعَيْبَتِي ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏","","",""],[12612,12612,"","আমরা যারা অল্প কিছু খুন করার জন্য পাগল হয়ে গেছি তাদের জন্য বলছি, আল্লাহ তা করতে হবে আর খারাপটা ঈশ্বরের কাছে আত্মসমর্পণ করবে, ঈশ্বরের দোহাই, আমি তোমাকে হত্যা করতে হবে। তুমি বলতে চাচ্ছ আমি যাচ্ছি আর তোমাকে বলব আমি কি করবো, খারাপ লোকেরা আসছে, তারপর তারা এটা বের করবে, আমি তোমার সাথে খুশি থাকব, তাই আমি তোমাকে বলছি, আমি যদি এটা কোন জায়গায় পাই তাহলে সেটা ভালো হত না। আর তাদের একটা দল বলেছিল, আমরা বলতে পারি যে সে তার মুখ দেখে ফেলে গেছে, যারা তাকে ভালোবাসে এবং কে ভালোবাসে। তাকে ভালবাসতো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ عَمَّهُ غَابَ عَنْ قِتَالِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ غِبْتُ مِنْ أَوَّلِ قِتَالٍ قَاتَلَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُشْرِكِينَ لَئِنْ اللَّهُ أَشْهَدَنِي قِتَالًا لِلْمُشْرِكِينَ لَيَرَيَنَّ اللَّهُ مَا أَصْنَعُ فَلَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏انْكَشَفَ الْمُسْلِمُونَ فَقَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعْتَذِرُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلَاءِ ‏ ‏يَعْنِي أَصْحَابَهُ ‏ ‏وَأَبْرَأُ إِلَيْكَ مِمَّا جَاءَ بِهِ هَؤُلَاءِ ‏ ‏يَعْنِي الْمُشْرِكِينَ ‏ ‏ثُمَّ تَقَدَّمَ فَلَقِيَهُ ‏ ‏سَعْدٌ ‏ ‏لِأُخْرَاهَا دُونَ ‏ ‏أُحُدٍ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏بِبَغْدَادَ ‏ ‏بِأُخْرَاهَا دُونَ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏أَنَا مَعَكَ قَالَ ‏ ‏سَعْدٌ ‏ ‏فَلَمْ أَسْتَطِعْ أَنْ أَصْنَعَ مَا صَنَعَ فَوُجِدَ فِيهِ ‏ ‏بِضْعٌ ‏ ‏وَثَمَانُونَ مِنْ بَيْنِ ضَرْبَةٍ بِسَيْفٍ وَطَعْنَةٍ بِرُمْحٍ وَرَمْيَةٍ بِسَهْمٍ قَالَ فَكُنَّا نَقُولُ فِيهِ وَفِي أَصْحَابِهِ نَزَلَتْ ‏ { ‏فَمِنْهُمْ مَنْ قَضَى ‏ ‏نَحْبَهُ ‏ ‏وَمِنْهُمْ مَنْ يَنْتَظِرُ ‏}","","",""],[12613,12613,"","আমরা অনেক কথা বলেছি, বাবা কিভাবে ছেলে মানে তা নিয়ে। আমি ভেবেছিলাম তোমার মত মানুষ আছে যারা তোমাকে নিজের জীবন খেয়ে ফেলার সুযোগ করে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَفْطَرَ عِنْدَ أُنَاسٍ قَالَ ‏ ‏أَفْطَرَ عِنْدَكُمْ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمْ الْأَبْرَارُ وَتَنَزَّلَتْ ‏ ‏عَلَيْكُمْ الْمَلَائِكَةُ ‏","","",""],[12614,12614,"","আমরা বলতে চেষ্টা করেছি, আমরা কত ক্লান্ত ও ক্লান্ত। আমি ঈশ্বরের কাছে যাবো আর তারা বলবে ভগবানের কাছে আছে আর আমি ঈশ্বরের দোহাই প্রার্থনা করবো। তারা আমাদের সর্বোচ্চ চেষ্টা করবে আপনি কি এবং কি","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏ومُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ قُولُوا وَعَلَيْكُمْ ‏","","",""],[12615,12615,"","আমরা ঈশ্বরের বড় হওয়ার জন্য একজন প্রভু হওয়ার কথা বলেছি... ...তারা বলেছিল, ঈশ্বর, তুমি প্রার্থনা করছো যে আমি তোমাদের কেউ না আর ভুল কিছু নই আমি থাকবো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي لَسْتُ كَأَحَدِكُمْ إِنِّي أَبِيتُ أُطْعَمُ وَأُسْقَى ‏","","",""],[12616,12616,"","আমরা কথা বলেছি, কিভাবে আমি ভবিষ্যদ্বাণীর ব্যাপারে তোমার টাকা ভুলে যেতে পারি, শহর এসে রানীকে খুঁজে বের করে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَدِينَةُ ‏ ‏يَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ الْمَلَائِكَةَ يَحْرُسُونَهَا فَلَا يَقْرَبُهَا ‏ ‏الدَّجَّالُ ‏ ‏وَلَا الطَّاعُونُ إِنْ شَاءَ اللَّهُ ‏","","",""],[12617,12617,"","আমরা ঈশ্বরের কাছে জিজ্ঞাসা করা একজন মাস্টারের সাথে কথা বলেছি আর সে মোটা-টা একটা আগুনে পুড়ে দেবে...","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَجُلٍ وَهُوَ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا ‏ ‏وَيْحَكَ ‏","","",""],[12618,12618,"","আমরা কথা দিয়েছি কিভাবে আমরা আপনার টাকা ভুলে গিয়েছিলাম যে ছেলেটি এটা রক্ষা করেছে এবং সে এটা করেনি. আমি তার প্রার্থনা এবং তার স্বাদ না দেখার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِيَعْتَدِلْ أَحَدُكُمْ فِي صَلَاتِهِ وَلَا يَفْتَرِشْ ذِرَاعَيْهِ كَالْكَلْبِ ‏","","",""],[12619,12619,"","আমরা অনেক অভিজ্ঞদের কথা বলেছি, যারা তোমার টাকা ভুলে গেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে আত্মসমর্পণ করবে আর তার মৃত্যু নিয়ে সে চিন্তা করবে, প্রভু আল্লাহ্‌ এক ঘন্টার জন্য বললেন যখন আমি ওকে মেরে ফেলি, সে বললো তুমি কার সাথে আছো, আমি তোমাকে ভালোবাসি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ خُنَيْسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ حَدَّثَهُمْ أَنَّ ‏ ‏رَجُلًا ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ فَقَالَ وَمَا أَعْدَدْتَ لِلسَّاعَةِ قَالَ حُبَّ اللَّهِ وَرَسُولِهِ قَالَ ‏ ‏أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12620,12620,"","আমরা দুজন তলোয়ারবাজের কথা বলেছি... ...আমার সব আত্মার ছেলে... ...যে বলেছে এটা কখনো হবে না, সে তার মেষশাবককে দিয়ে দেবে... সে চলে যাওয়ার পর, আমার বাবা আর আমার সাথে তার কোন সম্পর্ক নেই। আমি সবাইকে ফোন করবো যখন তুমি আমার বাবার সামনে এসে আমার বাবার সাথে থাকবে, আর লর্ডও ঠিক আছে। এটা এমন একটা আগুনের মতো। এটা অনেকটা আগুনের মতো। এটা একটা জায়গা। তার পঞ্চম আত্মা চলে যাবে যত তাড়াতাড়ি সে চলে যাবে আর মনে হবে সে চলে যাবে, ঈশ্বর আমার বাবাকে দিতে হবে, যাতে সে এটা করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَضَهُ الَّذِي تُوُفِّيَ فِيهِ أَتَاهُ ‏ ‏بِلَالٌ ‏ ‏يُؤْذِنُهُ بِالصَّلَاةِ فَقَالَ بَعْدَ مَرَّتَيْنِ يَا ‏ ‏بِلَالُ ‏ ‏قَدْ بَلَّغْتَ فَمَنْ شَاءَ فَلْيُصَلِّ وَمَنْ شَاءَ فَلْيَدَعْ فَرَجَعَ إِلَيْهِ ‏ ‏بِلَالٌ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي مَنْ ‏ ‏يُصَلِّي بِالنَّاسِ قَالَ ‏ ‏مُرْ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَلَمَّا أَنْ تَقَدَّمَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رُفِعَتْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السُّتُورُ قَالَ فَنَظَرْنَا إِلَيْهِ كَأَنَّهُ وَرَقَةٌ بَيْضَاءُ عَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏فَذَهَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَتَأَخَّرُ وَظَنَّ أَنَّهُ يُرِيدُ الْخُرُوجَ إِلَى الصَّلَاةِ فَأَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏أَنْ يَقُومَ فَيُصَلِّيَ فَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالنَّاسِ فَمَا رَأَيْنَاهُ بَعْدُ ‏","","",""],[12621,12621,"","আমরা সবচেয়ে ভালো সন্ত্রাসীদের মধ্যে ছিলাম আমরা শুনেছি যে আমি আপনার টাকা ভুলে গেছি যে এটা না, সে বলে যে আমি তোমাকে বলি না যে ইগোর অহংকার দেখতে। তারা আমাকে বলেছে যে নাবিক সিংহাসনের মধ্যে আছে, তোমার নাবিকের না, সে বলেছে আমি খুশি, আর তারপর সে তার কণ্ঠকে জাগিয়েছে। সব দিক থেকে ভালো বিজয়ের জন্য বলা.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونٍَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا بَلَى قَالَ دُورُ ‏ ‏بَنِي النَّجَّارِ ‏ ‏قَالَ أَلَا أُخْبِرُكُمْ بِالَّذِينَ يَلُونَهُمْ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ دُورُ ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏أَلَا أُخْبِرُكُمْ بِالَّذِينَ يَلُونَهُمْ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ دُورُ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏قَالَ ثُمَّ رَفَعَ صَوْتَهُ فَقَالَ فِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏","","",""],[12622,12622,"","আমি আপনার টাকা আপনার সাথে কথা বলার ব্যাপারে ভুলে গেছি। আমি যখন শুনেছি, ঈশ্বরের কাছে প্রার্থনা করে তার কাছে প্রার্থনা করলে তিনি জীবিতদের হাত থেকে মুক্তি পাবেন। যে লোক এই জন ্ য বেঁচে থাকবে সেই তো -- যদি সে মুমিন হয় আর সে মুমিন হয় , -- যে লোক এই জন ্ য বেঁচে থাকবে সেই তো -- যদি সে মুমিন হয় আর সে মুমিন হয় , -- যে লোক এই জন ্ য বেঁচে থাকবে সেই তো -- যদি সে মুমিন হয় আর সে মুমিন হয় , -- যে লোক এই জন ্ য বেঁচে থাকবে সেই তো -- যদি সে মুমিন হয় আর সে মুমিন হয় , -- যে লোক এই জন ্ য বেঁচে থাকবে সেই তো -- যদি সে মুমিন হয় আর সে মুমিন হয় , -- যে হবে চাঁদের মত হবে, সে আমাদের সময় ফাঁস করে দিচ্ছে এবং পুরুষদের বলছে যে, অনেক নারীই অযোগ্য।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَأُحَدِّثَنَّكُمْ بِحَدِيثٍ لَا يُحَدِّثُكُمْ بِهِ أَحَدٌ بَعْدِي سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ أَنْ يُرْفَعَ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيُشْرَبَ الْخَمْرُ وَيَظْهَرَ الزِّنَا وَيَقِلَّ الرِّجَالُ وَيَكْثُرَ النِّسَاءُ حَتَّى يَكُونَ ‏ ‏قَيِّمَ ‏ ‏خَمْسِينَ امْرَأَةً رَجُلٌ وَاحِدٌ ‏","","",""],[12623,12623,"","আমরা মেয়েদের টাকার প্রতি সবসময় আসক্ত থাকার বিরুদ্ধে তর্ক করেছি। ক্ষমতা, বলে যে এই ফ্লাস্ক আমাদের মধ্যে কেউ এটা বলতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي مَسِيرٍ لَهُ فَكَانَ ‏ ‏حَادٍ ‏ ‏يَحْدُو ‏ ‏بِنِسَائِهِ ‏ ‏أَوْ سَائِقٌ ‏ ‏قَالَ فَكَانَ نِسَاؤُهُ يَتَقَدَّمْنَ بَيْنَ يَدَيْهِ فَقَالَ يَا ‏ ‏أَنْجَشَةُ ‏ ‏وَيْحَكَ ‏ ‏ارْفُقْ ‏ ‏بِالْقَوَارِيرِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏هَذَا فِي الْحَدِيثِ مِنْ نَحْوِ قَوْلِهِ وَإِنْ وَجَدْنَاهُ ‏ ‏لَبَحْرًا ‏","","",""],[12624,12624,"","ঈশ্বরের ভালবাসার চেয়ে ভালো কথা বলেছি, ঈশ্বরের উপাসনা তোমার টাকা ভুলে যেতে হবে। কথাবার্তা আর সে তার মাংস পান করছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ دِهْقَانَ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ دِهْقَانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ أَوْ يَشْرَبَ بِشِمَالِهِ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فِي حَدِيثِهِ وَيَشْرَبَ بِشِمَالِهِ ‏","","",""],[12625,12625,"","আমরা যখন সেখানে পৌঁছাই, তখন আমরা তাদের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِهْقَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ ‏","","",""],[12626,12626,"","আমরা আপনার টাকা ভুলতে সক্ষম হয়েছি যে নবী এটা দিয়েছেন এবং তাকে উদ্ধার করেছেন। একটি গ্রীষ্মের সময়ে একটি প্রতিবেশী তার বন্ধুদের নিয়ে নির্মিত একটি এলাকা গড়ে উঠেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏وَجَعَلَ ذَلِكَ ‏ ‏صَدَاقَهَا ‏","","",""],[12627,12627,"","আমরা একজন ত্রাণকর্মীর ব্যাপারে কথা বলেছিলাম, যিনি বলেছিলেন যে ঈশ্বর আমাকে যে মিথ্যা কথা বলেছেন তা ইচ্ছাকৃতভাবে জন্ম নিচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَأَبُو قَطَنٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏ ‏وَلَمْ يَقُلْ ‏ ‏أَبُو قَطَنٍ ‏ ‏مُتَعَمِّدًا ‏","","",""],[12628,12628,"","আমরা দুঃখ প্রকাশ করে কথা বলেছি আর আমি একজন যাজকের কথা বলছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাকে তার আত্মা দিয়ে উদ্ধার করা হবে। আর এটা অনেক মজার ব্যাপার। আমি জানি, আমি কি বলেছি, আমি কি বলেছি? সব কিছু জানত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ الْوَاسِطِيُّ وَهُوَ الْمُزَنِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُصْعَبُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمْرٌ ‏ ‏فَجَعَلَ يَقْسِمُهُ ‏ ‏بِمِكْتَلٍ ‏ ‏وَاحِدٍ وَأَنَا رَسُولُهُ بِهِ حَتَّى فَرَغَ مِنْهُ قَالَ فَجَعَلَ يَأْكُلُ وَهُوَ ‏ ‏مُقْعٍ ‏ ‏أَكْلًا ‏ ‏ذَرِيعًا ‏ ‏فَعَرَفْتُ فِي أَكْلِهِ الْجُوعَ ‏","","",""],[12629,12629,"","আমরা কথা বলেছি, কিভাবে আমি আপনার টাকা ভুলে গিয়েছিলাম যে ছেলেটি তা করেছে এবং সে কত করেছে, চলো আমরা আগে করা যাক।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لِنَعْلَيْهِ ‏ ‏قِبَالَانِ ‏","","",""],[12630,12630,"","আমরা হামাদ বেনের টাকার কথা অনেক বেশি বলেছিলাম। তার ঈশ্বর.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ الْقِرَاءَةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[12631,12631,"","আমরা ঈশ্বরের কাছে প্রার্থনা করেছি তার শান্তির জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامَ حَتَّى نَقُولَ قَدْ أَوْهَمَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ السَّجْدَةِ جَلَسَ بَيْنَ السَّجْدَتَيْنِ حَتَّى نَقُولَ قَدْ أَوْهَمَ ‏","","",""],[12632,12632,"","আমরা হারুনের মধ্যে আছি যারা ঈশ্বরের সাথে কথা বলেছিল আমি আমার বাবা হবো, আশেপাশে শুয়ে আছি, মনে হচ্ছিল যেন একটা ক্লাসের মধ্যে মাতাল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَصَوْتُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فِي الْجَيْشِ أَشَدُّ عَلَى الْمُشْرِكِينَ مِنْ ‏ ‏فِئَةٍ ‏","","",""],[12633,12633,"","আমরা একজন সার্জনকে বলেছিলাম যে, আমি তোমার টাকা না। ভগবান তার জন্য প্রার্থনা করে বলেছিলেন যে সে এমন একজন মানুষ যে ছিল যে শুধু না নিজের দেশে ফিরে যাওয়ার অনুমতি দেওয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏كَيْفَ كَانَ شَعَرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ شَعَرًا رَجِلًا لَيْسَ ‏ ‏بِالسَّبْطِ ‏ ‏وَلَا ‏ ‏بِالْجَعْدِ ‏ ‏بَيْنَ أُذُنَيْهِ وَعَاتِقَيْهِ ‏","","",""],[12634,12634,"","আমরা একটা ছেলের কথা বলেছিলাম যে কাপুরুষের ছেলে ভুলে গেছে, আমি তাকে নিতে পারি, আমার প্রভু তার প্রতি দয়া করে থাকেন। তিনি ঈশ্বরের কাছে প্রার্থনা করেন এবং তিনি যদি চাইতেন, তাহলে তিনি তার কাছে প্রার্থনা করতেন। ঈশ্বর তাঁর মাথা উঁচু করে প্রার্থনা করতে বলেছেন। ( ২ করি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏جَارِيَةً ‏ ‏خَرَجَتْ عَلَيْهَا ‏ ‏أَوْضَاحٌ ‏ ‏فَأَخَذَهَا يَهُودِيٌّ ‏ ‏فَرَضَخَ ‏ ‏رَأْسَهَا وَأَخَذَ مَا عَلَيْهَا فَأُتِيَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِهَا ‏ ‏رَمَقٌ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَكِ فُلَانٌ فَقَالَتْ بِرَأْسِهَا لَا فَقَالَ فُلَانٌ فَقَالَتْ بِرَأْسِهَا لَا قَالَ فَفُلَانٌ الْيَهُودِيُّ فَقَالَتْ بِرَأْسِهَا نَعَمْ ‏ ‏فَأَخَذَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَضَخَ رَأْسَهُ بَيْنَ حَجَرَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏إِلَّا أَنَّ ‏ ‏قَتَادَةَ ‏ ‏قَالَ فِي حَدِيثِهِ فَاعْتَرَفَ الْيَهُودِيُّ ‏","","",""],[12635,12635,"","আমি বলতে চাই, প্রতিবেশী হচ্ছে আমার বাবার টাকা ভুলে যাওয়ার গোপন বিষয়, সে বলছে ঈশ্বর তার জন্য এসেছেন কিন্তু, তিনি যে - কাজ করেছিলেন, তা তার কাছে গুরুত্বপূর্ণ ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏رِبْعِيُّ بْنُ الْجَارُودِ بْنِ أَبِي سَبْرَةَ التَّمِيمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ أَبِي الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْجَارُودِ بْنِ أَبِي سَبْرَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يُصَلِّيَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏تَطَوُّعًا اسْتَقْبَلَ الْقِبْلَةَ فَكَبَّرَ لِلصَّلَاةِ ثُمَّ خَلَّى عَنْ رَاحِلَتِهِ فَصَلَّى حَيْثُمَا تَوَجَّهَتْ بِهِ ‏","","",""],[12636,12636,"","আমরা বাবাকে আমাদের ব্যাপারে যা বলেছে, তা দেওয়ার ব্যাপারে কথা বলেছি, ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন যদি সে তাকে হত্যা করতে যায়... ...তাহলে আমরা একজন উপযুক্ত প্রশাসনের সন্তান।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ لِلْغَائِطِ أَتَيْتُهُ أَنَا وَغُلَامٌ ‏ ‏بِإِدَاوَةٍ ‏ ‏وَعَنَزَةٍ ‏ ‏فَاسْتَنْجَى ‏","","",""],[12637,12637,"","আমরা তোমাকে বলেছিলাম কিভাবে আমরা তোমাকে বলেছিলাম যে আমি অনেক বৃদ্ধ। আমরা ঈশ্বরের কাছে অনুরোধ করছি না যে সে উপর হুকুম করেছে আর তাকে স্নাইপারদের কাছে পাঠিয়ে দেয়া হবে আর বলো যে, তোমার দয়া আর দয়া দেবতাদের.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏صَدَقَةُ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏وَقَّتَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَصِّ الشَّارِبِ وَتَقْلِيمِ الْأَظَافِرِ وَحَلْقِ ‏ ‏الْعَانَةِ ‏ ‏فِي كُلِّ أَرْبَعِينَ يَوْمًا مَرَّةً ‏","","",""],[12638,12638,"","আমরা একটা ছেলেকে গড়ে তুলে বলেছিলাম যে, আপনার টাকাপয়সা ভুলে যাওয়ার কথা । সে স্বর্গে যাচ্ছে, বলতে যাচ্ছে, \"অসম্ভবভাবে দেখা যায় না\" আমি খারাপ অনুভূতির মধ্যে দিয়ে যাচ্ছি, আর আমি কখনো কঠিন সময় দেখিনি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ يَوْمَ الْقِيَامَةِ فَيُصْبَغُ فِي النَّارِ صَبْغَةً ثُمَّ يُقَالُ لَهُ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏هَلْ رَأَيْتَ خَيْرًا قَطُّ هَلْ مَرَّ بِكَ نَعِيمٌ قَطُّ فَيَقُولُ لَا وَاللَّهِ يَا رَبِّ ‏ ‏وَيُؤْتَى بِأَشَدِّ النَّاسِ فِي الدُّنْيَا مِنْ أَهْلِ الْجَنَّةِ فَيُصْبَغُ فِي الْجَنَّةِ صَبْغَةً فَيُقَالُ لَهُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏هَلْ رَأَيْتَ ‏ ‏بُؤْسًا ‏ ‏قَطُّ هَلْ مَرَّ بِكَ ‏ ‏شِدَّةٌ ‏ ‏قَطُّ فَيَقُولُ لَا وَاللَّهِ يَا رَبِّ مَا مَرَّ بِي ‏ ‏بُؤْسٌ ‏ ‏قَطُّ وَلَا رَأَيْتُ ‏ ‏شِدَّةً ‏ ‏قَطُّ ‏","","",""],[12639,12639,"","আমরা ভুলে গিয়েছিলাম যে, কারেন আমাদের বলেছিলেন যে, তিনি বেঁচে আছেন । - তাই নাকি?","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏تَلَقَّيْنَا ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حِينَ قَدِمَ مِنْ ‏ ‏الشَّامِ ‏ ‏فَلَقِينَاهُ ‏ ‏بِعَيْنِ التَّمْرِ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي عَلَى دَابَّتِهِ لِغَيْرِ الْقِبْلَةِ فَقُلْنَا لَهُ إِنَّكَ تُصَلِّي إِلَى غَيْرِ الْقِبْلَةِ فَقَالَ لَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ذَلِكَ مَا فَعَلْتُ ‏","","",""],[12640,12640,"","আমাদের বলা হয়েছে, আমার বাবার সাথে কি ঘটেছে তা জানার চেষ্টা করার চেয়ে, আমার মাথায় যে মানুষ আছে, যখন আমি হাঙ্গর থেকে অন্ত্যেষ্টিক্রিয়া করব অথবা একটা ঘোড়া থেকে মুক্ত ঘোড়ায় বসে। দুই ছেলের মেয়ে তার আর আমাদের অনুগতদের চূড়ান্ত খেলায় তার কাছে এসেছে। আমাদের যেতে দেয়া যাবেনা.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو غَالِبٍ الْخَيَّاطُ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏صَلَّى عَلَى جِنَازَةِ رَجُلٍ فَقَامَ عِنْدَ رَأْسِهِ فَلَمَّا رُفِعَ أُتِيَ بِجِنَازَةِ امْرَأَةٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَوْ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقِيلَ لَهُ يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏هَذِهِ جِنَازَةُ فُلَانَةَ ابْنَةِ فُلَانٍ فَصَلِّ عَلَيْهَا فَصَلَّى عَلَيْهَا فَقَامَ وَسَطَهَا وَفِينَا ‏ ‏الْعَلَاءُ بْنُ زِيَادٍ الْعَدَوِيُّ ‏ ‏فَلَمَّا رَأَى اخْتِلَافَ قِيَامِهِ عَلَى الرَّجُلِ وَالْمَرْأَةِ قَالَ يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏هَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ مِنْ الرَّجُلِ حَيْثُ قُمْتَ وَمِنْ الْمَرْأَةِ حَيْثُ قُمْتَ قَالَ نَعَمْ قَالَ فَالْتَفَتَ إِلَيْنَا ‏ ‏الْعَلَاءُ ‏ ‏فَقَالَ احْفَظُوا ‏","","",""],[12641,12641,"","আমরা একটা স্বপ্নের কথা বলেছি যা তোমার টাকা ভুলে যাওয়ার চেয়ে ভালো। লর্ড তার কাছে প্রার্থনা করেছে, আর লর্ডের কাছে যাবে... তাকে আগুনের মধ্যে খুঁজে বের করতে অনেক কষ্ট হচ্ছে আর সে আগুনে নামবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَلْمٍ الْعَلَوِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ الْقَرْعُ مِنْ أَحَبِّ الطَّعَامِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ كَانَ الْقَرْعُ يُعْجِبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَكَّ ‏ ‏يَزِيدُ ‏ ‏فَأُتِيَ ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا قَرْعٌ فَرَأَيْتُهُ يُدْخِلُ أُصْبُعَيْهِ فِي الْمَرَقِ يَتْبَعُ بِهِمَا الْقَرْعَ السَّبَّابَةَ وَالْوُسْطَى فَرَّقَ بَيْنَهُمَا ثُمَّ ضَمَّهُمَا ‏","","",""],[12642,12642,"","আমরা তাকে বলেছিলাম কিভাবে আমরা তাকে বলেছিলাম একটি ভীতির ছেলে সম্পর্কে যে কিনা বলবে যে আমি একটা ছেলে হতে চাই যে আমি বলবো যে আমি একটা ছেলে হতে চাই যে আমি একটা ছেলে হতে চাই যে আমি একটা ছেলে হতে চাই যে হবে আমি তাকে বলতে চাই আমি ঈশ্বরের কাছে সাহায্য চাই তাকে আমার হাত দিয়ে সাহায্য করি আর আমি তাকে সাহায্য করব.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَتَّابًا ‏ ‏مَوْلَى ‏ ‏ابْنِ هُرْمُزَ ‏ ‏يَقُولُ ‏ ‏صَحِبْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏فِي سَفِينَةٍ فَسَمِعْتُهُ يَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي هَذِهِ وَأَشَارَ بِيَدِهِ عَلَى السَّمْعِ وَالطَّاعَةِ فِيمَا اسْتَطَعْتُ ‏","","",""],[12643,12643,"","আমরা তাদের কথা অনেক আগেই বলেছি যে মানুষ সবসময় এটা করে আসছে. দূরবীক্ষণ যন্ত্রের পুনরায় নামকরণ করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَلَمَّا دَفَنَّا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجَعْنَا قَالَتْ ‏ ‏فَاطِمَةُ ‏ ‏يَا ‏ ‏أَنَسُ ‏ ‏أَطَابَتْ أَنْفُسُكُمْ ‏ ‏أَنْ دَفَنْتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي التُّرَابِ وَرَجَعْتُمْ ‏","","",""],[12644,12644,"","আমরা একজন মাস্টারের কথা বলেছি যে হামাদকে আমরা একটা স্বপ্নের কথা বলেছি... ...যে কিনা ঈশ্বরের কাছে প্রার্থনা করেছে, আমার মায়ের বাড়িতে, মা আমাকে তার ডান কাজ করতে বাধ্য করেছে এবং আমাদের মায়ের দাস হিসেবে। জীবন।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏أُمِّ حَرَامٍ ‏ ‏فَأَقَامَنِي عَنْ يَمِينِهِ ‏ ‏وَأُمَّ حَرَامٍ ‏ ‏خَلْفَنَا ‏","","",""],[12645,12645,"","আমরা একটা কুত্তার বাচ্চা লুকিয়ে থাকার কথা বলেছিলাম, তারা আমাদের বলেছে আমার ভাইয়ের টাকা মুছে ফেলতে। সে বলেছে, সে নাকি তোমাদের জন্য বানানো হয়েছে, আগুন খাও, রাতের জন্য এটা খেয়ে যাচ্ছে। একটা কোক বা বাসা।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَهَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ ابْنُ أَخِي أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَطْرُقُ ‏ ‏أَهْلَهُ لَيْلًا كَانَ يَقْدَمُ ‏ ‏غُدْوَةً ‏ ‏أَوْ عَشِيَّةً ‏","","",""],[12646,12646,"","বাবার ক্ষমা চাইতে আমরা কথা বলেছিলাম, কিন্তু আমরা আমার নিজের বাবার ব্যাপারে কথা বলেছি, ঈশ্বরের প্রার্থনা তিনি এক মাস ধরে কাজ করার জন্য হাঁটু গেড়ে প্রার্থনা করবেন এবং তারপর তিনি আটকে থাকবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ أَبُو الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏","","",""],[12647,12647,"","আমাদের সবচেয়ে ভালো বন্ধুর সাথে বেনের সাথে আমরা কথা বলেছি, আমরা আমার বাবাকে ভালোবাসতে পারতাম। লর্ড তার জন্য প্রার্থনা করত এবং সে জন্মের যোগ্যতার জন্য আত্মসমর্পণ করবে। আমি জিজ্ঞেস করব, যদি আমি জিজ্ঞেস করি যে, \"যদি আমার সবচেয়ে ভালো বন্ধু হয়, \"মা\" তাহলে আমি আমার বাবা-কে ভালোবাসি।\" তারা বলল সে যদি তার সাথে আটকে থাকে... ...তাহলে তুমি ফোন করবে.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏وَابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ فَرَأَى حَبْلًا مَمْدُودًا بَيْنَ ‏ ‏سَارِيَتَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏فِي الْمَسْجِدِ ‏ ‏فَسَأَلَ عَنْهُ فَقَالُوا فُلَانَةُ تُصَلِّي فَإِذَا ‏ ‏غُلِبَتْ ‏ ‏تَعَلَّقَتْ بِهِ فَقَالَ ‏ ‏لِتُصَلِّ مَا عَقَلَتْ فَإِذَا ‏ ‏غُلِبَتْ ‏ ‏فَلْتَنَمْ ‏","","",""],[12648,12648,"","আমরা তোমার প্রভুর সাথে কথা বলেছি তোমার টাকা ভুলে যাওয়ার সময়... ...আর বলো, \"আমি ঈশ্বরকে দেখতে চাই না\" আমরা তাদের কাছে এসেছি তাদের চেয়ে ভালো। আমরা আগে এসেছি। আমরা অনেক ভালো। আমরা এখন অনেক ভালো আছি। ভয় হয়, সব ভাড়া করতে গিয়ে ঈশ্বর তাকে এটা করতে বলেছেন আর তিনি আমাকে এটা করতে বলেছেন.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏الْمُهَاجِرُونَ ‏ ‏يَا رَسُولَ اللَّهِ مَا رَأَيْنَا مِثْلَ قَوْمٍ قَدِمْنَا عَلَيْهِمْ أَحْسَنَ بَذْلًا مِنْ كَثِيرٍ وَلَا أَحْسَنَ مُوَاسَاةً فِي قَلِيلٍ قَدْ كَفَوْنَا ‏ ‏الْمَئُونَةَ ‏ ‏وَأَشْرَكُونَا فِي ‏ ‏الْمَهْنَإِ ‏ ‏فَقَدْ خَشِينَا أَنْ يَذْهَبُوا بِالْأَجْرِ كُلِّهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلَّا مَا أَثْنَيْتُمْ عَلَيْهِمْ بِهِ وَدَعَوْتُمْ اللَّهَ عَزَّ وَجَلَّ لَهُمْ ‏","","",""],[12649,12649,"","আমরা একজন অভিজ্ঞ মাস্টারের সাথে কথা বলেছি, যিনি বলেছেন যে তিনি হয়ত কোন দয়ায় দয়া দেখান না, তার কাছে টাকা আছে তাকে বর্ণনা করার জন্য যে সে সবচেয়ে ভালো মানুষ হতে যাচ্ছে। আমি তার অর্ধেক তরবারির প্রতি কৃতজ্ঞ । ঈশ্বর হারিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏مُهَاجِرًا آخَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏سَعْدِ بْنِ الرَّبِيعِ ‏ ‏فَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏لِي مَالٌ فَنِصْفُهُ لَكَ وَلِي امْرَأَتَانِ فَانْظُرْ أَحَبَّهُمَا إِلَيْكَ حَتَّى أُطَلِّقَهَا فَإِذَا انْقَضَتْ عِدَّتُهَا تَزَوَّجْهَا قَالَ فَقَالَ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ دُلُّونِي عَلَى السُّوقِ قَالَ فَمَا رَجَعَ يَوْمَئِذٍ حَتَّى رَجَعَ بِشَيْءٍ قَدْ أَصَابَهُ مِنْ السُّوقِ قَالَ وَفَقَدَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَّامًا ثُمَّ أَتَاهُ وَعَلَيْهِ ‏ ‏وَضَرُ ‏ ‏صُفْرَةٍ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْيَمْ ‏ ‏قَالَ تَزَوَّجْتُ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ مَا سُقْتَ إِلَيْهَا قَالَ ‏ ‏نَوَاةً ‏ ‏مِنْ ذَهَبٍ ‏ ‏أَوْ قَالَ وَزْنَ ‏ ‏نَوَاةٍ ‏ ‏مِنْ ذَهَبٍ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْلِمْ وَلَوْ بِشَاةٍ ‏","","",""],[12650,12650,"","তিনি কথা বলার জন্য কথা বলেন, অথবা তিনি যেভাবে বলেছিলেন, তা বলার জন্য তাকে বলতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏إِذَا حَدَّثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَفَرَغَ مِنْهُ قَالَ أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12651,12651,"","আমরা আমাদের সবচেয়ে ভালো বন্ধুর সাথে কথা বলেছি, আমার বাবা আমার বাবার সাথে বাস করা লোকদের অভ্যাসের জন্য লড়াই করবেন, আর আমি কখনোই আমার সাথে প্রেম করতে পারব না। যেমনটা তারা করেছিল, তারা যদি না থাকতো, তাহলে তারা করতো। ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ قِرَاءَتَهُمْ فِي صَلَاتِهِمْ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[12652,12652,"","আমরা বাবার ছেলেকে কথা বলেছি... ...মানুষ আমার ঘোড়ার জন্য বলেছে যে সে ঈশ্বরের দোহাই আর আমার ভাইয়ের কাছ থেকে একটা নাম পেয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَخَفِّ ‏ ‏أَوْ أَتَمِّ ‏ ‏النَّاسِ صَلَاةً ‏ ‏وَأَوْجَزِهِ ‏","","",""],[12653,12653,"","আমরা বাবার ছেলেকে বলেছিলাম একটা ঘোড়া নিয়ে যারা ঈশ্বরের কাছে তার শান্তি ও তার স্বপ্নের জন্য প্রার্থনা করতে যায়। তারা হিংস্রদের খেয়ে ফেলে। তারা বলে যে মানুষ আসবে। অন্য জনের পাপকে সব সময় ক্ষমা করা উচিত, আমরা কখনো হাত না দিয়ে লাফ দিইনি এবং আমরা কখনো ফুঁ দেই না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُهَاجِرُونَ ‏ ‏يَحْفِرُونَ ‏ ‏الْخَنْدَقَ ‏ ‏فِي ‏ ‏غَدَاةٍ ‏ ‏بَارِدَةٍ قَالَ ‏ ‏أَنَسٌ ‏ ‏وَلَمْ يَكُنْ لَهُمْ خَدَمٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنَّمَا الْخَيْرُ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ فَأَجَابُوهُ ‏ ‏نَحْنُ الَّذِينَ بَايَعُوا ‏ ‏مُحَمَّدًا ‏ ‏عَلَى الْجِهَادِ مَا بَقِينَا أَبَدًا ‏ ‏وَلَا ‏ ‏نَفِرُّ ‏ ‏وَلَا نَفِرُّ وَلَا نَفِرُّ ‏","","",""],[12654,12654,"","আমরা বাবার ছেলেকে বলেছিলাম একটা ঘোড়া সম্পর্কে... ...যে ন্যাংটা মেয়ে তাকে হত্যা করতে চেয়েছিল... ...সে তার জন্য প্রার্থনা করেছে, আর সে যদি চলে যায় তাহলে সে আত্মসমর্পণ করবে। আমি দুঃখিত, অথবা কোন মই যে প্রভুর অনুগ্রহে গিয়েছে... হাত দিয়ে তাদের যেতে দিন। আমরা হামিদকে বলেছি, যারা ঈশ্বরের উদ্দেশ্যের কাছ থেকে সরে এসেছে, সেই সমস্ত লোকদেরও যারা তার সাথে কথা বলেছে। কথা বলে সে শুধু অতীতেই কথা বলে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَسْلَمَ نَاسٌ مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ خَرَجْتُمْ إِلَى ‏ ‏ذَوْدٍ ‏ ‏لَنَا فَشَرِبْتُمْ مِنْ أَلْبَانِهَا ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَقَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَبْوَالِهَا فَفَعَلُوا فَلَمَّا صَحُّوا كَفَرُوا بَعْدَ إِسْلَامِهِمْ وَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤْمِنًا ‏ ‏أَوْ مُسْلِمًا ‏ ‏وَسَاقُوا ‏ ‏ذَوْدَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَرَبُوا مُحَارِبِينَ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آثَارِهِمْ فَأُخِذُوا فَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ وَتَرَكَهُمْ فِي ‏ ‏الْحَرَّةِ ‏ ‏حَتَّى مَاتُوا ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ وَذَكَرَ أَيْضًا فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏فَحَدَّثَ ‏ ‏قَتَادَةُ ‏ ‏فِي هَذَا الْحَدِيثِ وَأَبْوَالِهَا ‏","","",""],[12655,12655,"","আমরা বাবার ছেলেকে কথা বলেছি... ...জনগনের জন্য ঘোড়ার পিঠের কথা বলেছিলাম... ...আর ঈশ্বরের দয়া আর ঈশ্বরের দয়া।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَقَارِبَةً وَصَلَاةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏حَتَّى بَسَطَ ‏ ‏عُمَرُ ‏ ‏فِي صَلَاةِ ‏ ‏الْغَدَاةِ ‏","","",""],[12656,12656,"","আমরা বাবার ছেলেকে কথা বলেছিলাম... ...যে মানুষ সম্পর্কে সে আমাদের কথা বলেছে যে আমাদের কাছে অপরিচিতদের কাছে যেতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْمَغْرِبَ فِي بَيْتِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ نَأْتِي ‏ ‏بَنِي سَلِمَةَ ‏ ‏وَأَحَدُنَا يَرَى مَوَاقِعَ نَبْلِهِ ‏","","",""],[12657,12657,"","আমরা বাবার ছেলেকে বললাম, ঈশ্বর এটা দিয়েছেন এবং আমাকে শান্তি দিয়েছেন। আমরা ভেবেছিলাম, ছেলে তার প্রার্থনায় কেঁদেছে। গর্ভের মধ্যে ছিল.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِذْ سَمِعَ بُكَاءَ صَبِيٍّ ‏ ‏فَتَجَوَّزَ ‏ ‏فِي صَلَاتِهِ فَظَنَنَّا أَنَّهُ إِنَّمَا خَفَّفَ مِنْ أَجْلِ الصَّبِيِّ أَنَّ أُمَّهُ كَانَتْ فِي الصَّلَاةِ ‏","","",""],[12658,12658,"","আমরা বাবার ছেলের সাথে কথা বলেছি একটা হাত নিয়ে তাকে বলতে হবে ভালো যেতে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ عَذَابِ الْقَبْرِ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَعَوَّذُ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْجُبْنِ وَالْبُخْلِ وَفِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَعَذَابِ الْقَبْرِ ‏","","",""],[12659,12659,"","আমরা বাবার ছেলের সাথে কথা বলেছিলাম... ...তার সাথে দেখা করার জন্য... ...তার সাথে দেখা করার কথা ছিল.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَعَرَضَ رَجُلٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثَهُ ‏ ‏فَحَبَسَهُ ‏ ‏بَعْدَمَا أُقِيمَتْ الصَّلَاةُ حَتَّى نَعَسَ بَعْضُ الْقَوْمِ ‏","","",""],[12660,12660,"","আমরা বাবার ছেলেকে বলেছিলাম যে সে তার ছেলে যে সমস্ত লোকের জন্য প্রার্থনা করতো তারা ঈশ্বরের কাছে প্রার্থনা করতো আর পছন্দ করতো। তীর্থযাত্রীরা এগিয়ে আসছে আর সমর্থকরা জেগে উঠছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُحِبُّ أَنْ يَلِيَهُ فِي الصَّلَاةِ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏لِيَحْفَظُوا عَنْهُ ‏","","",""],[12661,12661,"","আমরা বাবার ছেলের সাথে কথা বলেছি... ...তার ছেলে যেখানে প্রার্থনা করছিল, সেই লোকদের জন্য... ...কিন্তু তার মেয়েরা কিছু একটা করে বলল, ঈশ্বর... প্রার্থনা করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَكَانَ بَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ نِسَائِهِ شَيْءٌ فَجَعَلَ يَرُدُّ بَعْضُهُنَّ عَلَى بَعْضٍ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏احْثُ ‏ ‏فِي أَفْوَاهِهِنَّ التُّرَابَ وَاخْرُجْ إِلَى الصَّلَاةِ ‏","","",""],[12662,12662,"","আমরা আমার বাবার ছেলেকে রক্ষা করার কথা বলেছি যারা তার সাথে ঝামেলা করতে ভুলে গেছে। প্রেসিডেন্ট তাঁর বিজয় এবং তাদের সন্তানদের কাছে কথা বলেছিলেন, তাই আপনাদের মতো জয়ের আত্মা। বলা হচ্ছে যে বিজয় হয়ত পরাজিত হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ذَاتَ يَوْمٍ وَهُوَ ‏ ‏مَعْصُوبُ ‏ ‏الرَّأْسِ قَالَ فَتَلَقَّاهُ ‏ ‏الْأَنْصَارُ ‏ ‏وَنِسَاؤُهُمْ وَأَبْنَاؤُهُمْ فَإِذَا هُوَ بِوُجُوهِ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنِّي لَأُحِبُّكُمْ وَقَالَ إِنَّ ‏ ‏الْأَنْصَارَ ‏ ‏قَدْ ‏ ‏قَضَوْا ‏ ‏مَا عَلَيْهِمْ وَبَقِيَ مَا عَلَيْكُمْ فَأَحْسِنُوا إِلَى مُحْسِنِهِمْ ‏ ‏وَتَجَاوَزُوا ‏ ‏عَنْ مُسِيئِهِمْ ‏","","",""],[12663,12663,"","আমরা বাবার ছেলেকে কথা বলেছি... ...একজনকে ভাঙ্গা মাত্র একজন মানুষ সম্পর্কে যখন বললো, সে আত্মসমর্পণ করেছে। সে তার মুখের সামনে বলেছে যে সে রক্ত দিয়েছে তার মুখ দিয়ে মুখ ঠিক করা দরকার যাতে সে তার রক্ত দিয়ে রক্ত তৈরি করে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏كُسِرَتْ ‏ ‏رَبَاعِيَةُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشُجَّ فِي وَجْهِهِ قَالَ فَجَعَلَ الدَّمُ يَسِيلُ عَلَى وَجْهِهِ فَجَعَلَ يَمْسَحُ الدَّمَ عَنْ وَجْهِهِ وَيَقُولُ ‏ ‏كَيْفَ يُفْلِحُ قَوْمٌ خَضَبُوا وَجْهَ نَبِيِّهِمْ بِالدَّمِ وَهُوَ يَدْعُوهُمْ إِلَى اللَّهِ عَزَّ وَجَلَّ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏}","","",""],[12664,12664,"","আমরা বাবার ছেলেকে কথা বলেছিলাম... ...যে লোকদের জন্য ঘোড়ার মত করে সে বলল, সে আমার হাত আঁকাচ্ছে, ঈশ্বরের কাছে প্রার্থনা করছে যেন সে তার আত্মাকে রক্ষা করে, তার এই কল্পনার দিকে তাকিয়ে তিনি বলেন, আল্লাহ তার প্রার্থনা করেছেন এবং তিনি বলবেন, \"ঈশ্বর, আমরা তোমার স্বাধীনতা মুক্ত করছি।\"","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ رَأْسَهُ مِنْ خَلْفِهِ يَنْظُرُ إِلَى مَوَاقِعِ نَبْلِهِ فَيَتَطَاوَلُ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِصَدْرِهِ ‏ ‏يَقِي بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَيَقُولُ يَا رَسُولَ اللَّهِ ‏ ‏نَحْرِي ‏ ‏دُونَ نَحْرِكَ ‏","","",""],[12665,12665,"","আমরা বাবার ছেলেকে বলেছিলাম একটা ঘোড়ার কথা। সে বললো, সে ঈশ্বরের পথে চলে গেছে। সে আমাকে এটা করতে বলেছে। সে বলল, সে ঈশ্বরের কাছে প্রার্থনা করে যেন রাতের বেলা তার জন্য প্রার্থনা করে। তোমাকে ধরে নিয়ে যাও আর তারা তাদের মন হারিয়ে ফেলতে চায় না, তারপর তাদের নামতে হবে এবং দৌড়ে যেতে হবে, তাদের গার্ডরা তাদের লড়াই করে, আর তাদের witchesরা লর্ড আর তাদের দেখে ফেলেছে ঈশ্বর তাকে এটা করতে দিয়েছেন আর ঈশ্বর তাকে ছাই দিয়েছে। অশুভ মানুষ বলেছে যে আমি আমার বাবাকে আর আমার বৃদ্ধ মানুষটি স্পর্শ করতে যাচ্ছি। প্রভু.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏خَيْبَرَ ‏ ‏فَانْتَهَى إِلَيْهَا لَيْلًا قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏طَرَقَ ‏ ‏لَيْلًا لَمْ ‏ ‏يُغِرْ ‏ ‏عَلَيْهِمْ حَتَّى يُصْبِحَ فَإِنْ سَمِعَ أَذَانًا ‏ ‏أَمْسَكَ ‏ ‏وَإِنْ لَمْ يَكُونُوا يُصَلُّونَ ‏ ‏أَغَارَ ‏ ‏عَلَيْهِمْ قَالَ فَلَمَّا أَصْبَحْنَا رَكِبَ وَرَكِبَ الْمُسْلِمُونَ قَالَ فَخَرَجَ أَهْلُ الْقَرْيَةِ إِلَى ‏ ‏حُرُوثِهِمْ ‏ ‏مَعَهُمْ ‏ ‏مَكَاتِلُهُمْ ‏ ‏وَمَسَاحِيهِمْ ‏ ‏فَلَمَّا رَأَوْا رَسُولَ اللَّهِ وَالْمُسْلِمِينَ قَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏وَاللَّهِ ‏ ‏وَالْخَمِيسُ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا ‏ ‏بِسَاحَةِ ‏ ‏قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ قَالَ ‏ ‏أَنَسٌ ‏ ‏وَإِنِّي لَرَدِيفُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏وَإِنَّ قَدَمِي لَتَمَسُّ قَدَمَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12666,12666,"","আমরা একজন অপরাধীর ছেলেকে এবং ঈশ্বর একটা পিপপির ছেলের বিষয়ে কথা বলেছিলাম । লোকেরা ভয় পেয়ে তাদের ভয় দেখে ভেবে দেখছে ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زِيَادٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُ رَأَى فِي يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏ ‏يَوْمًا وَاحِدًا ثُمَّ إِنَّ النَّاسَ ‏ ‏اضْطَرَبُوا ‏ ‏الْخَوَاتِيمَ مِنْ ‏ ‏وَرِقٍ ‏ ‏وَلَبِسُوهَا ‏ ‏فَطَرَحَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمَهُ ‏ ‏فَطَرَحَ ‏ ‏النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[12667,12667,"","আমরা বাবার সাথে দেখা করতে আসা একজন লোকের কথা বলেছিলাম যে আমি তোমার কথা শুনতে পাচ্ছি যে ঈশ্বর কি খেয়েছেন আর তার হাত আছে যাতে সে তার পিছু নেবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُرَارَةُ بْنُ أَبِي الْحَلَالِ الْعَتَكِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ وَبَيْنَ يَدَيْهِ مَرَقَةٌ فِيهَا ‏ ‏دُبَّاءٌ ‏ ‏فَجَعَلَ يَتَتَبَّعُهُ يَأْكُلُهُ ‏","","",""],[12668,12668,"","আমরা একটা অদ্ভুত চমকের কথা বলেছিলাম... ...আমি তোমার টাকা চাই সে বলে যে সে আমার সাথে দৌড়াচ্ছেনা... ...আর সে হয়তো অনেক কিছু করেছে আর মাঝে মাঝে সে হয়তো তার সাথে মানুষ হয়ে খুশি","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏هَلْ ‏ ‏خَضَبَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ رَأَى مِنْ الشَّيْبِ إِلَّا ‏ ‏يَعْنِي يَسِيرًا ‏ ‏وَقَدْ ‏ ‏خَضَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏أَحْسِبُ بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[12669,12669,"","ঈশ্বর বলে দিয়েছেন এবং বলবে, হ্যাঁ, হ্যাঁ, তিনি আপনাকে শক্তি দিয়ে চলে যাবেন ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُرَارَةُ بْنُ أَبِي الْحَلَالِ الْعَتَكِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏أَنْجَشَةُ ‏ ‏كَذَاكَ سَيْرُكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[12670,12670,"","আমরা আপনাদের পিছনে যেতে পেরে খুশি হলাম। লোকজন বললো, \"ঈশ্বর, খোদা\" অথবা Damien বলতে চায় যে এটা ভালো। তার দরজা এবং তার বাবা-মা তাকে কলজ থেকে রক্ষা করবে। তার বাবা-মা তাকে এই ব্রেসটি থেকে রক্ষা করবে যে সে হয়ত তার ভেতরে যেতে পারে। ( খ) কীভাবে আমরা জানি যে, যিহোবা আমাদের প্রার্থনার উত্তর দেন?","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ قَائِلًا مِنْ النَّاسِ قَالَ يَا نَبِيَّ اللَّهِ أَمَا يَرِدُ ‏ ‏الدَّجَّالُ ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ ‏ ‏أَمَا إِنَّهُ لَيَعْمِدُ إِلَيْهَا وَلَكِنَّهُ يَجِدُ الْمَلَائِكَةَ صَافَّةً ‏ ‏بِنِقَابِهَا ‏ ‏وَأَبْوَابِهَا يَحْرُسُونَهَا مِنْ ‏ ‏الدَّجَّالِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّهُ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَفَرَ ‏ ‏يُهَجَّاهُ يَقْرَؤُهُ كُلُّ مُؤْمِنٍ أُمِّيٍّ أَوْ ‏ ‏كَاتِبٍ ‏","","",""],[12671,12671,"","আমরা তোমার টাকা পাওয়ার ব্যাপারে সব ভালো বিজ্ঞানের কথা বলেছি, সে বলেছে আমার ভাই তার ভাই পছন্দ না হওয়া পর্যন্ত আমার ভাই কখনই নিরাপদ থাকবে না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا يُؤْمِنُ عَبْدٌ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ مِنْ الْخَيْرِ ‏","","",""],[12672,12672,"","আমরা কথা বলেছিলাম তিনি আমাকে বলতে চেয়েছিলেন তিনি আমাকে বলতে যে তিনি আমাকে বললেন কে যে তোমার বাবা তোমার ব্যথা চাইবে না","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُوسَى بْنُ أَنَسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مَنْ أَبِي قَالَ أَبُوكَ فُلَانٌ فَنَزَلَتْ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ ‏} ‏إِلَى تَمَامِ ‏ ‏الْآيَةَ ‏","","",""],[12673,12673,"","ঈশ্বর একটা স্যাচুরেশন বা একটা বালতি দিয়ে রেখেছেন, যা ভালো জিনিস হওয়ার আগেই ভালো কিছু করার জন্য উত্তম । এটা জেতার আগে, আমরা বলতে পারি যে আমরা শহরের পাগলের সাথে সুখে সুখে আছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أُكَيْدِرَ ‏ ‏دُومَةَ ‏ ‏أَهْدَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُبَّةَ ‏ ‏سُنْدُسٍ ‏ ‏أَوْ ‏ ‏دِيبَاجٍ ‏ ‏شَكَّ فِيهِ ‏ ‏سَعِيدٌ ‏ ‏قَبْلَ أَنْ يَنْهَى عَنْ الْحَرِيرِ فَلَبِسَهَا فَتَعَجَّبَ النَّاسُ مِنْهَا فَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَمَنَادِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ أَحْسَنُ مِنْهَا ‏","","",""],[12674,12674,"","তিনি বলেছেন, তিনি যেমন এফআরআই.আই লিখেছেন, তার লেখা কতগুলোই না আমার মায়ের নিরাপত্তা আর বই সে পড়ে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أَنْبَأَهُمْ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ بَيْنَ عَيْنَيْهِ مَكْتُوبٌ ‏ ‏ك ‏ ‏ف ‏ ‏ر أَيْ كَافِرٌ يَقْرَؤُهَا الْمُؤْمِنُ أُمِّيٌّ ‏ ‏وَكَاتِبٌ ‏","","",""],[12675,12675,"","আমরা তোমার টাকা ভুলের চেয়ে ভালো কথা বলেছি, সে বলেছিল আমি কী করতে চেয়েছিলাম। ঈশ্বর তার জন্য প্রার্থনা করেন এবং তিনি প্রার্থনা করেন এবং ঈশ্বরের দোহাই দিয়ে কখনো দোয়া করেন না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا صَلَّيْتُ خَلْفَ أَحَدٍ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْجَزَ صَلَاةً وَلَا أَتَمَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12676,12676,"","আমরা আমাদের ছেলের জন্য টাকা বাঁচানোর চেষ্টা করেছি। আমি বিশ্বাস করি না যে কেউ ঈশ্বর এবং আমি এটা পছন্দ করি যখন এটি কেবল আগুনের মধ্যে ছিল, আমরা বেঁচে আছি, এটা না। আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করতে পারি, তখন আমি তাকে জিজ্ঞেস করি, “আপনি কি সত্যিই তা জানেন? ”","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَحَتَّى يُقْذَفَ فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ أَنْ نَجَّاهُ اللَّهُ مِنْهُ وَلَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَنْصُورًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَلْقَ بْنَ حَبِيبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[12677,12677,"","আমরা তোমার টাকা ভুলের কথা বলেছিলাম... ...যা ভবিষ্যদ্বাণী করা হয়েছে আর এটা ঠিক করে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ثُمَّ رَكِبَ ‏ ‏رَاحِلَتَهُ ‏ ‏فَلَمَّا عَلَا ‏ ‏جَبَلَ الْبَيْدَاءِ ‏ ‏أَهَلَّ ‏","","",""],[12678,12678,"","আমরা তোমার টাকা নিয়ে ভুলের কথা বলেছিলাম আমি কখনো করেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি তাদের দেখতেও পারতেন।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ أَهْلَ ‏ ‏مَكَّةَ ‏ ‏سَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُرِيَهُمْ ‏ ‏آيَةً ‏ ‏فَأَرَاهُمْ انْشِقَاقَ الْقَمَرِ مَرَّتَيْنِ ‏","","",""],[12679,12679,"","আমরা যে নিয়ম সম্বন্ধে কথা বলেছিলাম, তা আমরা টাকা আয় করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ ‏ ‏لَا يَقْطَعُهَا ‏","","",""],[12680,12680,"","আমরা তাকে হত্যা করার ব্যাপারে কথা বলেছিলাম । তিনি বলেছিলেন, রাজা তার হাত দিয়ে এবং মাটির নিচে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا أَسِيرُ فِي الْجَنَّةِ إِذْ عَرَضَ لِي نَهَرٌ حَافَّتَاهُ ‏ ‏قِبَابُ ‏ ‏اللُّؤْلُؤِ الْمُجَوَّفِ فَقُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ رَبُّكَ قَالَ فَأَهْوَى الْمَلَكُ بِيَدِهِ فَأَخْرَجَ مِنْ طِينِهِ ‏ ‏مِسْكًا ‏ ‏أَذْفَرَ ‏","","",""],[12681,12681,"","আমরা সারাজীবন ধরে বলতেছি বাবা বিংশকে আমি কাকে খুঁজছি আমি তাকে মেনে নিতে পারি যে তিনি তার মৃত্যুর কাছাকাছি হলেও তাকে উদ্ধার করতে হবে। মাফ করবেন, প্রভু, তিনি কথা দিয়েছেন যে তিনি তাকে খুন করেছেন আর যে মানুষটি বলেছে তাকে খুন করেছে, আমি তাকে পছন্দ করি তাকে সে বলে যে তুমি যার যার সাথে আছ তার সাথে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي حَتَّى انْتَهَى إِلَى الْمَسْجِدِ قَرِيبًا مِنْهُ قَالَ أَتَاهُ ‏ ‏شَيْخٌ ‏ ‏أَوْ ‏ ‏رَجُلٌ ‏ ‏قَالَ مَتَى السَّاعَةُ يَا رَسُولَ اللَّهِ قَالَ وَمَا أَعْدَدْتَ لَهَا فَقَالَ الرَّجُلُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ صَلَاةٍ وَلَا صِيَامٍ وَلَكِنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ ‏ ‏فَأَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12682,12682,"","আমরা বাবাকে দেখেছি, যত তাড়াতাড়ি সম্ভব তিনি ভুলে যাওয়ার স্বপ্ন দেখেন। দশ বছর বা এরকম।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِشْرِينَ يَوْمًا ‏","","",""],[12683,12683,"","আমরা আপনার গ্রেসের উপর কিছু আবেগ নিয়ে কথা বলেছি, তিনি আছেন এবং তিনি তাদের সব চুরি করেছেন অথবা আমার বাবা।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَرَخَ ‏ ‏بِهِمَا ‏ ‏جَمِيعًا ‏ ‏أَوْ لَبَّى بِهِمَا جَمِيعًا ‏","","",""],[12684,12684,"","আমরা আপনাদের টাকাপয়সা হারানোর বিষয়ে কথা বলেছিলাম । তুমি পড়ে যাও, তুমি তার উত্তর দিবে না ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ فَتًى مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ الْجِهَادَ وَلَيْسَ لِي مَالٌ أَتَجَهَّزُ بِهِ فَقَالَ ‏ ‏اذْهَبْ إِلَى فُلَانٍ الْأَنْصَارِيِّ فَإِنَّهُ قَدْ كَانَ ‏ ‏تَجَهَّزَ ‏ ‏وَمَرِضَ فَقُلْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقْرِئُكَ السَّلَامَ وَيَقُولُ لَكَ ادْفَعْ إِلَيَّ مَا تَجَهَّزْتَ بِهِ فَقَالَ لَهُ ذَلِكَ فَقَالَ يَا فُلَانَةُ ادْفَعِي إِلَيْهِ مَا جَهَّزْتِنِي بِهِ وَلَا تَحْبِسِي عَنْهُ شَيْئًا فَإِنَّكِ وَاللَّهِ إِنْ حَبَسْتِ عَنْهُ شَيْئًا لَا يُبَارِكُ اللَّهُ لَكِ فِيهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏إِنَّ فَتًى مِنْ ‏ ‏أَسْلَمَ ‏","","",""],[12685,12685,"","আমরা আমার ভালবাসার কথা ভুলে যেতে বলেছিলাম, সে রাতে বা রাতে একটা ভালো কথা বলবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَغَدْوَةٌ ‏ ‏فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا ‏ ‏وَلَقَابُ قَوْسِ ‏ ‏أَحَدِكُمْ مِنْ الْجَنَّةِ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[12686,12686,"","স্বর্গকে বিকৃত করে এমন ব্যক্তি তাকে বলবে, যে আপনার বাড়ি থেকে এসেছে । সে বলবে, আমি যা বলবো, আমি আশা করি তুমি চাও না আমি তোমার নিজের পথে মরতে চাই। যে মানুষ আগুন খেয়ে তাকে বলবে, তোমার ছেলে, আমি যাদের কাছে যাব, সে বলবে আমরা ঈশ্বর। তুমি আমাকে তোমার কাজ করতে বলো.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى بِالرَّجُلِ مِنْ أَهْلِ الْجَنَّةِ فَيَقُولُ لَهُ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏كَيْفَ وَجَدْتَ مَنْزِلَكَ فَيَقُولُ أَيْ رَبِّ خَيْرُ مَنْزِلٍ فَيَقُولُ سَلْ وَتَمَنَّ فَيَقُولُ مَا أَسْأَلُ ‏ ‏وَأَتَمَنَّى إِلَّا أَنْ تَرُدَّنِي إِلَى الدُّنْيَا فَأُقْتَلَ فِي سَبِيلِكَ عَشْرَ مَرَّاتٍ لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ ‏ ‏وَيُؤْتَى بِالرَّجُلِ مِنْ أَهْلِ النَّارِ فَيَقُولُ لَهُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏كَيْفَ وَجَدْتَ مَنْزِلَكَ فَيَقُولُ أَيْ رَبِّ شَرُّ مَنْزِلٍ فَيَقُولُ لَهُ ‏ ‏أَتَفْتَدِي مِنْهُ ‏ ‏بِطِلَاعِ ‏ ‏الْأَرْضِ ذَهَبًا فَيَقُولُ أَيْ رَبِّ نَعَمْ فَيَقُولُ كَذَبْتَ قَدْ سَأَلْتُكَ أَقَلَّ مِنْ ذَلِكَ وَأَيْسَرَ فَلَمْ تَفْعَلْ فَيُرَدُّ إِلَى النَّارِ ‏","","",""],[12687,12687,"","আমরা তোমার টাকা ভুলের কথা বলেছিলাম, এটা বলা যে, এটা করার ক্ষমতা ছিল। বছর ধরে আমাদের অন্ধকারে যেতে বলা হয়েছে, আমি শুনেছি ভবিষ্যদ্বাণীটা তার কাছে প্রার্থনা করেছে আর সে বলেছে আমরা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ فِي دُعَائِهِ ‏ ‏اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِثَابِتٍ ‏ ‏أَسَمِعَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[12688,12688,"","আমরা আপনাদের টাকা ভুলে গিয়ে একটা নিশ্চিত কথা বলেছিলাম যে, তিনি তাঁর শান্তির জন্য ঈশ্বরকে পাঠিয়েছিলেন । আমি তার বাড়িকে চ্যালেঞ্জ করেছিলাম যাতে সে সেই সমস্ত লোকেদের মধ্যে বিভক্ত করে, যারা তাকে বিবাহবিচ্ছেদের জন্য দায়ী করে ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَى الْجَمْرَةَ ثُمَّ ‏ ‏نَحَرَ ‏ ‏الْبُدْنَ ‏ ‏وَالْحَجَّامُ ‏ ‏جَالِسٌ ثُمَّ قَالَ لِلْحَجَّامِ ‏ ‏وَوَصَفَ ‏ ‏هِشَامٌ ‏ ‏ذَلِكَ ‏ ‏وَوَضَعَ يَدَهُ عَلَى ‏ ‏ذُؤَابَتِهِ ‏ ‏فَحَلَقَ أَحَدَ شِقَّيْهِ الْأَيْمَنَ وَقَسَمَهُ بَيْنَ النَّاسِ وَحَلَقَ الْآخَرَ فَأَعْطَاهُ ‏ ‏أَبَا طَلْحَةَ ‏","","",""],[12689,12689,"","আমি যখন আমার বাবা - মায়ের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম, তখন আমি তাদের সঙ্গে কথা বলেছিলাম । যখন আমরা ক্লান্ত হয়ে পড়েছিলাম, তখন আমার জন্য ভালো লাগছে, একটা ছেলের দুঃখ... ...আমরা শুনেছি যে, তোমার টাকা বলতে গেলে এটা ঠিক না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ثَابِتًا الْبُنَانِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَتَمَنَّ أَحَدُكُمْ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي مَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏وَعَبْدَ الْعَزِيزِ بْنَ صُهَيْبٍ ‏ ‏قَالَا سَمِعْنَا ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏بِمِثْلِهِ إِلَّا أَنَّهُ قَالَ مِنْ ضُرٍّ نَزَلَ بِهِ ‏","","",""],[12690,12690,"","আমি আমার বাবার সাথে কথা বলেছি, আমি ঈশ্বরের কাছে প্রার্থনা করব, যখন সে বলবে আমি কি করছি। আমি বন্ধু নই, কিন্তু আমি ইশ্বরের মত। তুমি আমার পছন্দ করো।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَنْصُورًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَتَى السَّاعَةُ فَقَالَ مَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ صِيَامٍ وَلَا صَلَاةٍ وَلَا صَدَقَةٍ وَلَكِنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ ‏ ‏أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12691,12691,"","আমরা আপনার টাকা নিয়ে কথা বলেছি আমি যা বলতে চাইছি, ঈশ্বর দোষ দিতে চান যদি তিনি বলেন তিনি একজন ভালো মানুষ, বাবা, যদি প্রার্থনা কোনো সুযোগ না থাকে, তিনি বিশ্বকে হত্যা করবেন। প্রার্থনা।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ سَعْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا أَعْرِفُ شَيْئًا مِمَّا عَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَوْمَ فَقَالَ ‏ ‏أَبُو رَافِعٍ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏وَلَا الصَّلَاةَ فَقَالَ أَوَلَيْسَ قَدْ عَلِمْتَ مَا صَنَعَ ‏ ‏الْحَجَّاجُ ‏ ‏فِي الصَّلَاةِ ‏","","",""],[12692,12692,"","আমি হয়তো তার এতিমখানায় গিয়ে বলতে শুনেছিলাম যে, তিনি হয়তো বলতে পারেন, ‘ আমাকে বলার পর আমি আমার বাবার কাছে প্রার্থনা করেছিলাম । আর বধিরদের পরে সে বলে যে তুমি মারা যাচ্ছ, ভালোবাসাটা ভাল জীবন।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ مَشَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخُبْزِ شَعِيرٍ ‏ ‏وَإِهَالَةٍ ‏ ‏سَنِخَةٍ ‏ ‏وَلَقَدْ رَهَنَ ‏ ‏دِرْعًا ‏ ‏لَهُ عِنْدَ يَهُودِيٍّ فَأَخَذَ شَعِيرًا لِأَهْلِهِ وَلَقَدْ سَمِعْتُهُ ذَاتَ يَوْمٍ يَقُولُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏يَقُولُ ذَلِكَ مِرَارًا ‏ ‏مَا أَمْسَى عِنْدَ آلِ ‏ ‏مُحَمَّدٍ ‏ ‏صَاعُ ‏ ‏بُرٍّ ‏ ‏وَلَا ‏ ‏صَاعُ ‏ ‏حَبٍّ وَإِنَّ عِنْدَهُ تِسْعَ نِسْوَةٍ حِينَئِذٍ ‏","","",""],[12693,12693,"","আমরা কথা বলেছিলাম যে সে কিভাবে বের হয়েছে যে সে তোমার টাকা ভুলে গেছে। আমার ভবিষ্যদ্বাণী তাকে তার মায়ের কাছে ডেকেছে আর আমি আমার ফোনটি সবার কাছে লিখে দিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ دَعْوَةً قَدْ دَعَا بِهَا فِي أُمَّتِهِ وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي ‏","","",""],[12694,12694,"","আমি বাবার উপর একটা আঘাত পাওয়ার কথা বলেছিলাম, তারপর সে এটা করতে গেলে সে তার নিজের শাস্তি দিবে। যুদ্ধটা তাকে ভেতরে ঢুকতে দিবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيُصِيبَنَّ نَاسًا ‏ ‏سَفْعٌ ‏ ‏مِنْ النَّارِ عُقُوبَةً بِذُنُوبٍ عَمِلُوهَا ثُمَّ لَيُدْخِلُهُمْ اللَّهُ الْجَنَّةَ بِفَضْلِ رَحْمَتِهِ يُقَالُ لَهُمْ الْجَهَنَّمِيُّونَ ‏","","",""],[12695,12695,"","আমরা আমার বাবা তোমার টাকা ভুলে যাওয়ার সিদ্ধান্ত নিয়ে কথা বলেছি, নবী যে এটা করেছে, তার ফোন আমি তোমার আর আনন্দ নিয়ে নিচ্ছি আর চলে যাই বন্য, মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي دُعَائِهِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ ‏","","",""],[12696,12696,"","ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমি সেই গুরুতর অপরাধকারীদের কাছে প্রার্থনা করব, যারা ঈশ্বরের বিরুদ্ধে অপরাধ স্বীকার করবে । আগুন, তিনবার আগুন ধরে আগুনের শিখাতে বললো।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ اللَّهَ الْجَنَّةَ ثَلَاثًا قَالَتْ الْجَنَّةُ اللَّهُمَّ أَدْخِلْهُ الْجَنَّةَ وَمَنْ اسْتَعَاذَ بِاللَّهِ مِنْ النَّارِ ثَلَاثًا قَالَتْ النَّارُ اللَّهُمَّ أَعِذْهُ مِنْ النَّارِ ‏","","",""],[12697,12697,"","এমনকি তিনি হয়তো বলেন যে, তিনি হয়তো শান্ত হবেন এবং বলতে পারেন যে, তিনি হয়তো আমার কাছে অবাক হয়ে যাবেন ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ حَتَّى يُقَالَ قَدْ صَامَ وَيُفْطِرُ حَتَّى يُقَالَ قَدْ أَفْطَرَ ‏","","",""],[12698,12698,"","আমরা একটা গেমের কথা বলেছিলাম বাবা বলেছে যে আমি একটা ছেলেকে শুনেছি যে সে কথা বলেছে... ...সে বলেছে সে উঠে যাবে আর তার সাথে থাকবে না আর পালাতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَسِّرُوا وَلَا تُعَسِّرُوا وَأَسْكِنُوا وَلَا تُنَفِّرُوا ‏","","",""],[12699,12699,"","আমার কাছে ঈশ্বরের কাছে আছে এবং আমাকে তার কানে কান দিতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏سَلْمٍ الْعَلَوِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَخْدُمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَدْخُلُ عَلَيْهِ بِغَيْرِ إِذْنٍ فَجِئْتُ ذَاتَ يَوْمٍ فَدَخَلْتُ عَلَيْهِ فَقَالَ ‏ ‏يَا بُنَيَّ إِنَّهُ قَدْ حَدَثَ أَمْرٌ فَلَا تَدْخُلْ عَلَيَّ إِلَّا بِإِذْنٍ ‏","","",""],[12700,12700,"","আমরা তোমার টাকা জেতার কথা বলেছিলাম, নয়তো আমি চুমু খেতে চাই যদি আমাকে বলা হয় যে সে উত্তর দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَوْ أُهْدِيَ إِلَيَّ ‏ ‏كُرَاعٌ ‏ ‏لَقَبِلْتُ وَلَوْ دُعِيتُ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏إِلَيْهِ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏عَلَيْهِ ‏ ‏لَأَجَبْتُ ‏","","",""],[12701,12701,"","আমরা ঈশ্বর ও তাঁর শান্তি সম্বন্ধে ভুলে যাওয়ার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏فَلَمَّا ‏ ‏تَجَلَّى ‏ ‏رَبُّهُ لِلْجَبَلِ ‏} ‏قَالَ ‏ ‏فَأَوْمَأَ ‏ ‏بِخِنْصَرِهِ قَالَ ‏ ‏فَسَاخَ ‏","","",""],[12702,12702,"","আমরা বলেছিলাম যে সে কিভাবে শাসিত হয়েছে যে তার কাছে টাকা ছিল, তুমি বাঁধার অযোগ্য হবে না আর তুমি অমর হয়ে যাবে না","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَاطَعُوا وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[12703,12703,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে বাধা দেবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَزَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَاطَعُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثِ لَيَالٍ ‏","","",""],[12704,12704,"","আমরা একটা মোলে নিয়ে কথা বলেছিলাম, যখন তিনি মারা যান । তাকে ফোন করে তার আলো স্পর্শ করা।","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ وَرْدَانَ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ صَلَّيْتُمْ ‏ ‏يَعْنِي الْعَصْرَ قَالُوا نَعَمْ قُلْنَا أَخْبِرْنَا أَصْلَحَكَ اللَّهُ مَتَى كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي هَذِهِ الصَّلَاةَ قَالَ كَانَ ‏ ‏يُصَلِّيهَا وَالشَّمْسُ بَيْضَاءُ نَقِيَّةٌ ‏","","",""],[12705,12705,"","আমি আমার বাবার সাথে যুদ্ধ করার জন্য যুদ্ধ করা নিয়ে প্রেসের সাথে কথা বলেছি। ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং মৃগয়াটি দিয়েছিলেন। একটা প্ল্যান খুজে বের করে তার ঋণ রক্ষা করে।","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النُّخَاعَةُ ‏ ‏فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا ‏","","",""],[12706,12706,"","আমরা দু - বছর আগে কথা বলেছিলাম যে জোনসের সঙ্গে আমরা বিয়ের কথা বলেছিলাম, যারা ঈশ্বরকে বলতে চেয়েছিল তাদের সম্বন্ধে । তোমার আত্মা.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏ ‏لَهُ فَصٌّ حَبَشِيٌّ وَنَقَشَهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[12707,12707,"","আমরা হয়তো ইশ্বরের একটা ছেলে ছিল, যে তোমাকে শুনতে পেত। যদি ঈশ্বরের দোহাই তাঁর নিজের শান্তি থাকতো, আর তাকে তার একমাত্র মেয়েকে ভিক্ষা দিতে দেয়া হতো।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَغْتَسِلُ وَالْمَرْأَةُ مِنْ نِسَائِهِ مِنْ الْإِنَاءِ الْوَاحِدِ ‏","","",""],[12708,12708,"","আমরা একজন মাস্টারের কথা বলেছি যে তোমাকে ভুলে যাবে... ...সে বলেছে যে তোমাকে কে জানে.","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏خَالِدٍ يَعْنِي الْحَذَّاءَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏هَلْ ‏ ‏قَنَتَ ‏ ‏عُمَرُ ‏ ‏قَالَ نَعَمْ وَمَنْ هُوَ خَيْرٌ مِنْ ‏ ‏عُمَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الرُّكُوعِ ‏","","",""],[12709,12709,"","আমি মানুষের কথা বলেছিলাম, আমি আল্লাহ্‌কে বলব আমি ঋণ শোধ করছি আর শেষ জন ভাল আছে.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَدْعُوَ يَقُولُ ‏ ‏اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏","","",""],[12710,12710,"","আমরা প্রায় তিন সপ্তাহ ধরে শুনেছি যে মানুষ বলছে এটা আল্লাহ্‌। এমনকি তার ভুল দেখতেও হাত বাড়িয়ে দিয়েছে। আমি শুনেছি, যারা বলেছে, আল্লাহ তাদের কথা। আমি বলেছি, আল্লাহই বলেছেন, এটা আমার মনে হয় যেন আমি এটা শুনেছি। আমি বলেছি, আমি বলছি, এটা শুনেই আল্লাহ্‌। আমি বললাম, আমি মনে করি, আমি যদি আমার জীবনের সব কিছু পরিবর্তন করি, আমি জানি, আমি যদি ভুল করি, আমি জানি, আমি জানি, আমি কি করেছি। আমি জানি, আমি জানি, আমি কি বলছি, আমি জানি, আমি কি বলছি, আমি জানি, আমি কি বলছি, আমি জানি, আমি কি করেছি। তার কাছ থেকে শুনেছি খোদা ঈশ্বরের কাছে ক্ষমা প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ فِي الدُّعَاءِ حَتَّى يُرَى بَيَاضُ إِبِطَيْهِ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِعَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا ذَاكَ فِي ‏ ‏الِاسْتِسْقَاءِ قَالَ قُلْتُ أَسَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ سُبْحَانَ اللَّهِ قَالَ قُلْتُ أَسَمِعْتَهُ مِنْهُ قَالَ سُبْحَانَ اللَّهِ ‏","","",""],[12711,12711,"","আমরা যারা আমাদের কথা বলেছি তারা আমাদের বলেছে কিভাবে তাদের জন্য যুদ্ধ করতে হয় যাদের বাবা মা আছে. মুক্ত কাপড় দিয়ে তারা তাকে স্পর্শ করবে আর মনে হচ্ছে তারা এটা নিয়ে যেতে চাচ্ছে এই থেকে অথবা এর মধ্যে না","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِثَوْبٍ حَرِيرٍ فَجَعَلُوا يَمَسُّونَهُ وَيَنْظُرُونَ فَقَالَ أَتَعْجَبُونَ مِنْ هَذَا ‏ ‏لَمَنَادِيلُ ‏ ‏سَعْدٍ ‏ ‏أَوْ مِنْدِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ خَيْرٌ مِنْ هَذَا ‏ ‏أَوْ أَلْيَنُ مِنْ هَذَا ‏","","",""],[12712,12712,"","আমরা একটি ভাল ছেলের সাথে টোপ নিয়ে কথা বলেছি. শুনুন, মানুষ তাকে ঈশ্বরের কাছে পৌঁছে দিয়েছে, তাকে উদ্ধার করেছেন যিনি আমাকে বলেছেন তাকে যেন বলা হয় যে আমাদের এটা সেলাই করতে হবে আর বিয়ের পর সেটা পরে পরে পরে হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏وَعَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏وَعَتَّابٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ هُرْمُزَ ‏ ‏وَرَابِعٍ ‏ ‏أَيْضًا ‏ ‏سَمِعُوا ‏ ‏أَنَسًا ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏ ‏كَذَا ‏ ‏قَالَ لَنَا أَخْطَأَ فِيهِ وَإِنَّمَا هُوَ ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏","","",""],[12713,12713,"","আমরা সাইমন আর বাবা'র সাথে কথা বলেছি... ...আমি একজন যাজক হওয়ার জন্য খুশি। আমি ভাববাদীর কাছে প্রার্থনা করে ভুলবো আর আমি বলবো যে তুমি জানো আমি কি বলবো,","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏يَعْنِي ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ أَنَسٍ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[12714,12714,"","আমরা গরু দিয়ে লড়াই করার কথা বলেছি, যারা ভগবানের কাছে অনুরোধ করেছে, তারা দুঃখটা খাচ্ছিল, অন্য কারো জন্য না।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَهُمْ يَحْفِرُونَ ‏ ‏الْخَنْدَقَ ‏ ‏اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرَ ‏ ‏الْآخِرَهْ ‏ ‏فَأَصْلِحْ ‏ ‏الْأَنْصَارَ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[12715,12715,"","আমরা কথা বলেছি আপনার টাকা নিয়ে কথা বলতে সমস্যা হচ্ছে। ঈশ্বর বলেছেন, ঈশ্বর জিতে গেছেন এবং আমরা আমার কথা ভেবেছি এবং যদি সে আমাকে ফোন করে তার সাথে আছি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ إِذَا دَعَانِي ‏","","",""],[12716,12716,"","আমরা একটা ছেলেকে হারানোর কথা বলেছি যাকে বলা হয় ভালো জীবন, তার নাম দেয়া হয়েছে, লর্ড তাকে আত্মসমর্পণ করে আমি তোমাকে মেরে ফেলবো... যদি তারা আত্মসমর্পণ না করত আপনি বলতে এবং আপনি করতে হবে","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدِ بْنِ أَنَسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏فَسَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا أَضْرِبُ عُنُقَهُ قَالَ لَا ‏ ‏إِذَا سَلَّمُوا عَلَيْكُمْ فَقُولُوا وَعَلَيْكُمْ ‏","","",""],[12717,12717,"","আমরা যে বধিরদের কথা বলেছিলাম, আমরা আমার ছেলেদের গলা কেটে কথা বলেছিলাম, সে এটা ছেড়ে দেবে, কিন্তু আমি ভয় পাচ্ছি সে পেশাদার নয়, সে এত কঠিন হয়ে পড়েছে যে ভালটা ভালো ছিল। তোমাকে প্রতারিত করা হয়েছে, তুমি লর্ডের বার্তাবাহককে বদলেছ, তাকে এটা উদ্ধার করতে হবে, তার আদেশ আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏بُرْدٌ ‏ ‏نَجْرَانِيٌّ غَلِيظُ ‏ ‏الْحَاشِيَةِ ‏ ‏وَأَعْرَابِيٌّ يَسْأَلُهُ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏حَتَّى انْتَهَى إِلَى بَعْضِ حُجَرِهِ ‏ ‏فَجَذَبَهُ جَذْبَةً حَتَّى انْشَقَّ ‏ ‏الْبُرْدُ ‏ ‏وَحَتَّى تَغَيَّبَتْ ‏ ‏حَاشِيَتُهُ ‏ ‏فِي عُنُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ مِنْ تَغْيِيرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَمَرَ لَهُ بِشَيْءٍ فَأُعْطِيَهُ ‏","","",""],[12718,12718,"","আমরা সেই বধিরদের কথা বলেছি যারা এটা করতে এসেছিল, তাদের জয় করতে হবে। প্রধান হিসেবে দেখা গেছে, এই ড্রামটা ছিল নবী তার কাছে প্রার্থনা করেছিলেন এবং তিনি আমাকে তিনটি বিশেষ ঘটনাও হত্যা করতে পারতেন। অথবা সে আপনার শত্রু অথবা আমি বোকা। আমার মুখে পাওয়া এক মহিলার চমৎকার বৃত্ত আমার ভাই, যার সঙ্গে আমি পুরুষ। যে পুরুষ পুরুষ পুরুষ ও নারী নারী নারী নারী নারী, সে একজন পুরুষ পুরুষ পুরুষ যিনি নারী নারী, সে নারী নারী নারী, যে পুরুষ পুরুষ এবং নারী নারী। যে নারী নারী নারী নারী নারী, সে নারী নারী, যে নারী নারী নারী, সে পুরুষ যে নারী নারী, সে পুরুষ, সে নারী, যে পুরুষ এবং নারী নারী। যে নারী নারী নারী নারী নারী, সে নারী নারী, যে নারী নারী নারী, সে পুরুষ যে নারী নারী, সে পুরুষ, সে নারী, যে পুরুষ এবং নারী নারী। যে নারী নারী নারী নারী নারী, সে নারী নারী, যে নারী নারী নারী, সে পুরুষ যে নারী নারী, সে পুরুষ, সে নারী, যে পুরুষ এবং নারী নারী। যে নারী নারী নারী নারী নারী, সে নারী নারী নারী, যে পুরুষ পুরুষ পুরুষী নারী, সে নারী নারী নারী, যে নারী নারী নারী নারী, যে পুরুষ পুরুষ পুরুষী নারী। সে একজন নারী যে নারী নারী এবং নারী নারী, সে একজন পুরুষ। আমি বিয়ে করছি আর আমি আবার খেলতে চাচ্ছি। আমরা ওকে মারতে পারব, আর ছেলেকে বলতে পারি যে তাদের হাতে দুই সপ্তাহ কাজ আছে আর আমার ছেলে হতে হবে যুদ্ধ করার আর দেখা যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا بَعَثَ ‏ ‏حَرَامًا ‏ ‏خَالَهُ أَخَا ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فِي سَبْعِينَ رَجُلًا فَقُتِلُوا يَوْمَ ‏ ‏بِئْرِ مَعُونَةَ ‏ ‏وَكَانَ رَئِيسُ الْمُشْرِكِينَ يَوْمَئِذٍ ‏ ‏عَامِرُ بْنُ الطُّفَيْلِ ‏ ‏وَكَانَ هُوَ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اخْتَرْ مِنِّي ثَلَاثَ خِصَالٍ يَكُونُ لَكَ أَهْلُ السَّهْلِ وَيَكُونُ لِي ‏ ‏أَهْلُ الْوَبَرِ ‏ ‏أَوْ أَكُونُ خَلِيفَةً مِنْ بَعْدِكَ أَوْ أَغْزُوكَ ‏ ‏بِغَطَفَانَ ‏ ‏أَلْفِ أَشْقَرَ وَأَلْفِ شَقْرَاءَ قَالَ فَطُعِنَ فِي بَيْتِ امْرَأَةٍ مِنْ بَنِي فُلَانٍ فَقَالَ ‏ ‏غُدَّةٌ ‏ ‏كَغُدَّةِ ‏ ‏الْبَعِيرِ فِي بَيْتِ امْرَأَةٍ مِنْ بَنِي فُلَانٍ ائْتُونِي بِفَرَسِي فَأُتِيَ بِهِ فَرَكِبَهُ فَمَاتَ وَهُوَ عَلَى ظَهْرِهِ فَانْطَلَقَ ‏ ‏حَرَامٌ ‏ ‏أَخُو ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَرَجُلَانِ مَعَهُ رَجُلٌ مِنْ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏وَرَجُلٌ أَعْرَجُ فَقَالَ لَهُمْ كُونُوا قَرِيبًا مِنِّي حَتَّى آتِيَهُمْ فَإِنْ آمَنُونِي وَإِلَّا كُنْتُمْ قَرِيبًا فَإِنْ قَتَلُونِي أَعْلَمْتُمْ أَصْحَابَكُمْ قَالَ فَأَتَاهُمْ ‏ ‏حَرَامٌ ‏ ‏فَقَالَ أَتُؤْمِنُونِي أُبَلِّغْكُمْ رِسَالَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْكُمْ قَالُوا نَعَمْ فَجَعَلَ يُحَدِّثُهُمْ وَأَوْمَئُوا إِلَى رَجُلٍ مِنْهُمْ مِنْ خَلْفِهِ فَطَعَنَهُ حَتَّى أَنْفَذَهُ بِالرُّمْحِ قَالَ اللَّهُ أَكْبَرُ فُزْتُ وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ ثُمَّ قَتَلُوهُمْ كُلَّهُمْ غَيْرَ الْأَعْرَجِ كَانَ فِي رَأْسِ جَبَلٍ قَالَ ‏ ‏أَنَسٌ ‏ ‏فَأُنْزِلَ عَلَيْنَا وَكَانَ مِمَّا يُقْرَأُ ‏ ‏فَنُسِخَ ‏ ‏أَنْ بَلِّغُوا قَوْمَنَا أَنَّا لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا قَالَ ‏ ‏فَدَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِمْ أَرْبَعِينَ صَبَاحًا عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏الَّذِينَ عَصَوْا اللَّهَ وَرَسُولَهُ ‏","","",""],[12719,12719,"","আমরা সেই বধিরদের কথা বলেছিলাম যারা আমার কাছে এসেছিল আর ভুলে গিয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُنْبَذَ ‏ ‏الْبُسْرُ ‏ ‏وَالتَّمْرُ جَمِيعًا ‏","","",""],[12720,12720,"","আমরা সেই বধির ব্যক্তিদের কথা বলেছি যাদের আমরা ঈশ্বরের কাছে যাওয়ার কথা বলেছিলাম। তুমি যদি জানো আমি কি জানি, তুমি একটু কম, তুমি একটু একটু কম। তুমি অনেক কম ছিলে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[12721,12721,"","আমরা ঐ বধিরদের কথা বলেছিলাম, বাবার সাথে কাজ করার চেষ্টা করাটা ভালো না, এটা কাজ করবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ الْعَبْدُ بِخَيْرٍ مَا لَمْ يَسْتَعْجِلْ قَالُوا وَكَيْفَ يَسْتَعْجِلُ قَالَ يَقُولُ قَدْ دَعَوْتُ رَبِّي فَلَمْ يَسْتَجِبْ لِي ‏","","",""],[12722,12722,"","আমরা সেই বধির ও আরও উত্তম পুত্র সম্বন্ধে কথা বলেছিলাম, যাদের আমরা কীভাবে শাসন করেছিলাম, সেই বিষয়ে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا قَالَ ‏ ‏لَا إِيمَانَ لِمَنْ لَا أَمَانَةَ لَهُ وَلَا دِينَ لِمَنْ لَا عَهْدَ لَهُ ‏","","",""],[12723,12723,"","আমরা যে বধিরদের কথা বলেছিলাম, সে ব্যাপারে কথা বলেছি, তাজা পানি ভালো, আমি খুব জিনিয়াস নই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ حَارِثَةَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنْ كَانَ ‏ ‏حَارِثَةُ ‏ ‏أَصَابَ خَيْرًا وَإِلَّا أَكْثَرْتُ الْبُكَاءَ قَالَ يَا ‏ ‏أُمَّ حَارِثَةَ ‏ ‏إِنَّهَا ‏ ‏جِنَانٌ ‏ ‏كَثِيرَةٌ وَإِنَّهُ لَفِي الْفِرْدَوْسِ الْأَعْلَى ‏","","",""],[12724,12724,"","তিনি এক বন্ধ্যা ও বিভ্রান্তকর প্রথার কাছে তার জীবন উৎসর্গ করেছিলেন । উত্তর দিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ يَهُودِيًّا ‏ ‏دَعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى خُبْزِ شَعِيرٍ ‏ ‏وَإِهَالَةٍ ‏ ‏سَنِخَةٍ ‏ ‏فَأَجَابَهُ ‏","","",""],[12725,12725,"","কিন্তু, আমি তাদের মন ও তাদের হাত দিয়ে তাদের আত্মা ভরে ফেলতে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏أَقْرَنَيْنِ ‏ ‏يَذْبَحُهُمَا بِيَدِهِ وَيَضَعُ رِجْلَهُ عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏وَيُسَمِّي وَيُكَبِّرُ ‏","","",""],[12726,12726,"","আমরা সেই বধিরদের কথা বলেছি যারা তাকে স্পর্শ করার উপায় দিয়ে গিয়েছিল কিন্তু আমার কাছে খুন করা এবং অন্ত্যেষ্টিক্রিয়ার মাধ্যমে চলে যাওয়াটা ভাল ছিল, আর তারপর আমাকে এটা করতে হবে আমি একাই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مُرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ فَأُثْنِيَ عَلَيْهَا خَيْرًا فَقَالَ وَجَبَتْ وَمُرَّ بِجِنَازَةٍ فَأُثْنِيَ عَلَيْهَا شَرًّا فَقَالَ وَجَبَتْ ‏","","",""],[12727,12727,"","আমরা আমার বাবার সাথে আমার বাবার যা হয়েছে তার কথা বলেছিলাম আমার ভালোবাসা হারিয়ে যাওয়ার কথা তিনি কয়েক সেকেন্ড সময় হাল ছেড়ে দেবেন আর প্রার্থনা করলেন তিনি বিগ বাবা-কে নিয়ে যাবেন আর তিনি হবেন। ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি আমাদের কাছে আত্মসমর্পণ করেছেন আর তার নিজের হাত আছে । ঈশ্বর, প্রভু ও প্রভু ঈশ্বর ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمْ يَخْرُجْ إِلَيْنَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا ‏ ‏وَأُقِيمَتْ ‏ ‏الصَّلَاةُ فَذَهَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَتَقَدَّمُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحِجَابِ فَرَفَعَهُ فَلَمَّا ‏ ‏وَضَحَ ‏ ‏لَنَا وَجْهُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَظَرْنَا مَنْظَرًا قَطُّ كَانَ أَعْجَبَ إِلَيْنَا مِنْ وَجْهِ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏وَضَحَ ‏ ‏لَنَا ‏ ‏فَأَوْمَأَ ‏ ‏بِيَدِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏أَنْ يَتَقَدَّمَ وَأَرْخَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحِجَابَ فَلَنْ يَقْدِرَ عَلَيْهِ حَتَّى مَاتَ ‏","","",""],[12728,12728,"","বাবার সাথে যা ঘটেছে তার কথা আমরা কথা বলেছি, আমরা যে অন্ত্যেষ্টিক্রিয়ার কথা বলেছি, তা নিয়ে কথা বলেছি। মহান ভাই আর ভাই, কোন ছেলে কখনোই জানবে না যে মানুষ কখনোই বলে না। মানুষ আমাকে ভয় দেখায় কারণ আমি তাকে হারাতে যাচ্ছি। যারা তাদের হত্যা করেছে, তাদের হয়তো ভুল হয়েছে, প্রভু, আমরা হয়ত বলেছিলাম যে সে এটা করেছে। ঈশ্বরের দোহাই দিয়ে তিনি প্রথম দিন ছিল হারিয়ে যাওয়া শেষ দিন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং পরীর কাছে আত্মসমর্পণ করেছেন এবং তারপর তিনি প্রভুর জয়ে এগিয়ে গেছেন। প্রভু, তারা তাদের শান্তি দেবে এবং বলবে প্রভু তোমাদের উপর দিয়ে যাবেন তারা ঈশ্বরের শহর হত্যা করতে বলেছে, তারা আমার ছেলেকে দেখেছে। তারা বলল আমার ঈশ্বর আমার কাছে এসে তারা বলল যে তিনি আমার কাছে এসেছেন। বাবা বলছে, ঈশ্বর একটা স্বপ্ন, আর তিনি হল হল হলওয়ের মধ্যে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আমার কাছে ফিরে আসবেন। তিনি বলেছিলেন, ঈশ্বর ঈশ্বরের কাছে আছে। তিনি বললেন, পিতা আমাকে বললেন, ঈশ্বর যেন আমি আমার কাছে ফিরে যাই। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি তোমার জন্য এটা করতে পারি। আর আমি যদি আমার বাবা আমাকে ছেড়ে দেই। এবং আমি যদি চাই, আমি জানি, আমি জানি না যে, আমি তোমার কাছে এটা করতে পারি। আর আমি যদি আমার বাবা আমাকে ছেড়ে দেব। আর আমি সত্যিই চাই, আমি জানি যে, আমি তোমার জন্য এটা করতে পারি। আর আমি জানি না যে, আমি তোমার জন্য এটা করতে পারি। আর আমি জানি না যে, আমি জানি, আমি তোমার জন্য এটা একটা উদ্দেশ্য ছিল। আর আমি যদি আমার বাবাও না। আর আমি জানি না যে, আমি জানি না। সে বলছিল যে সে কোন পুলিশ হবে না, ঈশ্বর বলে দিয়েছেন, আমি ঈশ্বরের দয়ায় এসেছি, আমি তোমাকে ঈশ্বরের কাছে পৌঁছে দিতে চাই। আমি নিশ্চিত তুমি ঠিক হয়ে যাবে। আর আমি তাদের প্রভু এবং আমি তাদেরকে শিক্ষা দিচ্ছি তাদের ব্যর্থ করতে। ঈশ্বর আমার জন্য যা শিক্ষা প্রদান করেন, আমি বলবো আমরা তাকে কি শিক্ষা দেব। আমি জানি, আমরা যা তাকে শিক্ষা দিচ্ছি। আমি কি জানি?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏وَهُوَ ‏ ‏مُرْدِفٌ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏شَيْخٌ يُعْرَفُ وَنَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَابٌّ لَا يُعْرَفُ قَالَ ‏ ‏فَيَلْقَى الرَّجُلُ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَيَقُولُ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏مَنْ هَذَا الرَّجُلُ الَّذِي بَيْنَ يَدَيْكَ فَيَقُولُ هَذَا الرَّجُلُ يَهْدِينِي إِلَى السَّبِيلِ فَيَحْسِبُ الْحَاسِبُ أَنَّهُ إِنَّمَا ‏ ‏يَهْدِيهِ الطَّرِيقَ وَإِنَّمَا ‏ ‏يَعْنِي سَبِيلَ الْخَيْرِ فَالْتَفَتَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَإِذَا هُوَ بِفَارِسٍ قَدْ لَحِقَهُمْ فَقَالَ يَا نَبِيَّ اللَّهِ هَذَا فَارِسٌ قَدْ لَحِقَ بِنَا قَالَ فَالْتَفَتَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ اصْرَعْهُ فَصَرَعَتْهُ فَرَسُهُ ثُمَّ قَامَتْ ‏ ‏تُحَمْحِمُ ‏ ‏قَالَ ثُمَّ قَالَ يَا نَبِيَّ اللَّهِ مُرْنِي بِمَا شِئْتَ قَالَ قِفْ مَكَانَكَ لَا تَتْرُكَنَّ أَحَدًا يَلْحَقُ بِنَا قَالَ فَكَانَ أَوَّلُ النَّهَارِ جَاهِدًا عَلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ آخِرُ النَّهَارِ ‏ ‏مَسْلَحَةً ‏ ‏لَهُ قَالَ فَنَزَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَانِبَ ‏ ‏الْحَرَّةِ ‏ ‏ثُمَّ بَعَثَ إِلَى ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءُوا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمُوا عَلَيْهِمَا وَقَالُوا ارْكَبَا آمِنَيْنِ مُطْمَئِنَّيْنِ قَالَ فَرَكِبَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَحَفُّوا حَوْلَهُمَا بِالسِّلَاحِ قَالَ فَقِيلَ ‏ ‏بِالْمَدِينَةِ ‏ ‏جَاءَ نَبِيُّ اللَّهِ ‏ ‏فَاسْتَشْرَفُوا ‏ ‏نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُونَ إِلَيْهِ وَيَقُولُونَ جَاءَ نَبِيُّ اللَّهِ فَأَقْبَلَ يَسِيرُ حَتَّى جَاءَ إِلَى جَانِبِ دَارِ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالُوا فَإِنَّهُ لَيُحَدِّثُ أَهْلَهَا إِذْ سَمِعَ بِهِ ‏ ‏عَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏وَهُوَ فِي نَخْلٍ لِأَهْلِهِ ‏ ‏يَخْتَرِفُ ‏ ‏لَهُمْ مِنْهُ فَعَجِلَ أَنْ يَضَعَ الَّذِي ‏ ‏يَخْتَرِفُ ‏ ‏فِيهَا فَجَاءَ وَهِيَ مَعَهُ فَسَمِعَ مِنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعَ إِلَى أَهْلِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ بُيُوتِ أَهْلِنَا أَقْرَبُ قَالَ فَقَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏أَنَا يَا نَبِيَّ اللَّهِ هَذِهِ دَارِي وَهَذَا بَابِي قَالَ فَانْطَلِقْ فَهَيِّئْ لَنَا ‏ ‏مَقِيلًا ‏ ‏قَالَ فَذَهَبَ فَهَيَّأَ لَهُمَا مَقِيلًا ثُمَّ جَاءَ فَقَالَ يَا نَبِيَّ اللَّهِ قَدْ هَيَّأْتُ لَكُمَا ‏ ‏مَقِيلًا ‏ ‏فَقُومَا عَلَى بَرَكَةِ اللَّهِ ‏ ‏فَقِيلَا ‏ ‏فَلَمَّا جَاءَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏فَقَالَ أَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ حَقًّا وَأَنَّكَ جِئْتَ بِحَقٍّ وَلَقَدْ عَلِمَتْ ‏ ‏الْيَهُودُ ‏ ‏أَنِّي سَيِّدُهُمْ وَابْنُ سَيِّدِهِمْ وَأَعْلَمُهُمْ وَابْنُ أَعْلَمِهِمْ فَادْعُهُمْ فَاسْأَلْهُمْ فَدَخَلُوا عَلَيْهِ فَقَالَ لَهُمْ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ ‏ ‏الْيَهُودِ ‏ ‏وَيْلَكُمْ اتَّقُوا اللَّهَ فَوَالَّذِي لَا إِلَهَ إِلَّا اللَّهُ إِنَّكُمْ لَتَعْلَمُونَ أَنِّي رَسُولُ اللَّهِ حَقًّا وَأَنِّي جِئْتُكُمْ بِحَقٍّ أَسْلِمُوا قَالُوا مَا نَعْلَمُهُ ثَلَاثًا ‏","","",""],[12729,12729,"","আমরা আমার বাবার সাথে কথা বলেছি, আমরা ভালোবাসার কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ الْحَبْحَابِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدَّجَّالُ ‏ ‏مَمْسُوحُ الْعَيْنِ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏ ‏يُهَجَّاهَا يَقْرَؤُهُ كُلُّ مُسْلِمٍ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏","","",""],[12730,12730,"","আমরা সেই বধিরদের কথা বলেছি যেটা আমার বাবার সাথে হয়েছে... ...তোমার টাকা ভুলে গিয়ে... ...তোমার টাকা ঈশ্বরের কাছে যাওয়ার কথা ভুলে গেছে। সে তিন বার রাস্তায় শ্বাস নিচ্ছে আর বলে সে বলছে সে নাকি... সে বলবে সে দুইবার বা না কাউকে জিজ্ঞেস করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِصَامٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَنَفَّسُ فِي الشَّرَابِ ثَلَاثًا وَيَقُولُ إِنَّهُ أَدْوَأُ وَأَبْرَأُ ‏ ‏وَأَمْرَأُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَأَنَا أَتَنَفَّسُ ثَلَاثًا ‏","","",""],[12731,12731,"","আমি যখন ছোট ছিলাম, তখন আমার বাবা আমাকে বলেছিলেন যে, আমি একজন বধির ব্যক্তি । পৃথিবীর শপথের মাধ্যমে তাকে উদ্ধার করা হবে, তারা আমাকে দশ রাতের লড়াই করবে আর তারপর সে আমাকে খুন করবে। ঈশ্বর তার জন্য প্রার্থনা করেছে এবং সে তার যাত্রা পথে যাত্রা করেছে। বাবা ও তার বাবার সঙ্গে আমার ছেলেকে নিয়ে যাওয়ার জন্য তিনি প্রার্থনা করছিলেন । তারপর আমি তাকে মেরে ফেলব।\" সে বলেছিল, সে শয়তানের কবরে ছিল এবং তার আত্মার প্রাণে ছিল। রাজা, গৃহহীনদের পরবর্তী অংশ, তারা অনুসন্ধান করা হয় এবং গথস হত্যা করা হয়। তিনি বললেন, তারা আপনার পাথরটি সরিয়ে নিয়ে যাবে এবং তারা ঈশ্বরের জয়ে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو التَّيَّاحِ يَزِيدُ بْنُ حُمَيْدٍ الضُّبَعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ فِي عُلُوِّ ‏ ‏الْمَدِينَةِ ‏ ‏فِي حَيٍّ يُقَالُ لَهُ ‏ ‏بَنُو عَمْرِو بْنِ عَوْفٍ ‏ ‏فَأَقَامَ فِيهِمْ أَرْبَعَ عَشْرَةَ لَيْلَةً ثُمَّ إِنَّهُ أَرْسَلَ إِلَى ‏ ‏مَلَإٍ ‏ ‏مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏قَالَ فَجَاءُوا مُتَقَلِّدِينَ سُيُوفَهُمْ قَالَ فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رِدْفُهُ ‏ ‏وَمَلَأُ ‏ ‏بَنِي النَّجَّارِ ‏ ‏حَوْلَهُ حَتَّى أَلْقَى ‏ ‏بِفِنَاءِ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ فَكَانَ ‏ ‏يُصَلِّي حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ وَيُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ ثُمَّ إِنَّهُ أَمَرَ بِالْمَسْجِدِ فَأَرْسَلَ إِلَى مَلَإٍ مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏فَجَاءُوا فَقَالَ يَا ‏ ‏بَنِي النَّجَّارِ ‏ ‏ثَامِنُونِي ‏ ‏حَائِطَكُمْ ‏ ‏هَذَا فَقَالُوا وَاللَّهِ لَا نَطْلُبُ ثَمَنَهُ إِلَّا إِلَى اللَّهِ قَالَ وَكَانَ فِيهِ مَا أَقُولُ لَكُمْ كَانَتْ فِيهِ قُبُورُ الْمُشْرِكِينَ وَكَانَ فِيهِ ‏ ‏حَرْثٌ ‏ ‏وَكَانَ فِيهِ نَخْلٌ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقُبُورِ الْمُشْرِكِينَ ‏ ‏فَنُبِشَتْ ‏ ‏وَبِالْحَرْثِ فَسُوِّيَتْ وَبِالنَّخْلِ فَقُطِعَ قَالَ فَصَفُّوا النَّخْلَ إِلَى قِبْلَةِ الْمَسْجِدِ وَجَعَلُوا ‏ ‏عِضَادَتَيْهِ ‏ ‏حِجَارَةً قَالَ وَجَعَلُوا يَنْقُلُونَ ذَلِكَ الصَّخْرَ وَهُمْ ‏ ‏يَرْتَجِزُونَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُمْ يَقُولُ ‏ ‏اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَانْصُرْ ‏ ‏الْأَنْصَارَ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[12732,12732,"","বাবার সাথে আমার বাবার যা হয়েছে তার কথা আমরা বললাম। আমরা বাবা বলেছিলাম আমরা যাদের কথা বলেছি তাদের সম্পর্কে। সে একটা মই থাকবে, আর আমি একজন ভালো মানুষ হব। গলা কেটে, তার ভাইও নিশ্চয়ই বলবে যে তার বাবা কিছু একটা করেছেন। ভগবান এটা করেছেন আর তার মনও দিয়েছেন যে তিনি কখনোই এরকম করেনি। প্রার্থনা আমাদের বাড়িতে আছে, যে সমস্ত অসঙ্গত কামনার আদেশ দেয়া হবে, সে আত্মসমর্পণ করবে এবং আমরা তার উত্তরাধিকারীর কাছে প্রার্থনা করব, আমরা বলেছিলাম তারা নাকি কেবল এই এলাকারই ছিল। ভিতরে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْسَنَ النَّاسِ خُلُقًا وَكَانَ لِي أَخٌ يُقَالُ لَهُ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏قَالَ أَحْسِبُهُ قَالَ فَطِيمًا ‏ ‏فَقَالَ وَكَانَ إِذَا جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَآهُ قَالَ ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏ ‏قَالَ ‏ ‏نُغَرٌ ‏ ‏كَانَ يَلْعَبُ بِهِ ‏ ‏قَالَ فَرُبَّمَا تَحْضُرُهُ الصَّلَاةُ وَهُوَ فِي بَيْتِنَا فَيَأْمُرُ بِالْبِسَاطِ الَّذِي تَحْتَهُ فَيُكْنَسُ ثُمَّ ‏ ‏يُنْضَحُ ‏ ‏بِالْمَاءِ ثُمَّ يَقُومُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَقُومُ خَلْفَهُ فَيُصَلِّي بِنَا قَالَ وَكَانَ بِسَاطُهُمْ مِنْ جَرِيدِ النَّخْلِ ‏","","",""],[12733,12733,"","আমরা সেই সব মানুষের কথা বলেছি যারা বলেছে নবী আল্লাহকে রক্ষা করেছে আর তার জন্ম দিয়েছেন। তার মন, তারপর সে টেনে টেনে নিয়ে যায়, কিংবা টেনে নিয়ে যায়, সে ছেলেটিকে বিদায় জানানোর শিক্ষা দিল, ঈশ্বরের দিনকে বলে ডাকতে ভালোবাসে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏حِينَ وُلِدَ وَهُوَ ‏ ‏يَهْنَأُ ‏ ‏بَعِيرًا لَهُ وَعَلَيْهِ عَبَاءَةٌ فَقَالَ مَعَكَ تَمْرٌ فَنَاوَلْتُهُ تَمَرَاتٍ فَأَلْقَاهُنَّ فِي ‏ ‏فِيهِ ‏ ‏فَلَاكَهُنَّ ‏ ‏ثُمَّ ‏ ‏فَغَرَ ‏ ‏فَاهُ ثُمَّ ‏ ‏أَوْجَرَهُنَّ ‏ ‏إِيَّاهُ فَجَعَلَ ‏ ‏يَتَلَمَّظُ ‏ ‏الصَّبِيُّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُبُّ ‏ ‏الْأَنْصَارِ ‏ ‏التَّمْرَ وَسَمَّاهُ ‏ ‏عَبْدَ اللَّهِ ‏","","",""],[12734,12734,"","আমরা সেই বধির ব্যক্তিদের কথা বলেছি যারা শাসক হওয়ার কথা বলেছিল এবং যারা লর্ড ছিল তাদের সবাই শপথ করে বলছি। সে আপনাকে আমি যে কথাগুলো বলব, সে সব কথা বলে যা তুমি শেষ করে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَالْقَاسِمِ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَلَّمَ عَلَيْكُمْ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏فَقُولُوا عَلَيْكُمْ ‏ ‏وَقَالَ ‏ ‏الْآخَرُ وَعَلَيْكُمْ ‏","","",""],[12735,12735,"","আমি দুঃখিত, দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏وَهُمْ أَرَقُّ قُلُوبًا مِنْكُمْ وَهُمْ أَوَّلُ مَنْ جَاءَ بِالْمُصَافَحَةِ ‏","","",""],[12736,12736,"","আমরা সেই বধিরদের কথা বলেছি যাদের নিয়ে আমরা কথা বলেছি, আপনার টাকা যাওয়ার জন্য প্রস্তুত হয়ে যাওয়া নিয়ে। রমজানে তিনি রাত কাটাতে পারবেন, তারপর তিনি চলে যাবেন এবং তারপর তিনি মারা যাবেন। সে একবার করেছে, যখন আমি বলবো, প্রভু, তখন তুমি আমাকে এমন করলে আর আমি করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثُمَامَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَوْهُ لَيْلَةً فِي رَمَضَانَ وَصَلَّى لَهُمْ فَخَفَّفَ ثُمَّ دَخَلَ فَأَطَالَ الصَّلَاةَ ثُمَّ خَرَجَ فَصَلَّى بِهِمْ ثُمَّ دَخَلَ فَأَطَالَ الصَّلَاةَ فَفَعَلَ ذَلِكَ مِرَارًا فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ أَتَيْنَاكَ فَفَعَلْتَ كَذَا وَكَذَا فَقَالَ ‏ ‏مِنْ أَجْلِكُمْ فَعَلْتُ ذَلِكَ ‏","","",""],[12737,12737,"","আমরা বধিরদের কথা বলেছি এবং আপনাদের টাকা ভুলে আমাদের মনকে তৈরি করেছি। ঈশ্বর আমার প্রিয় বন্ধু, ঈশ্বর তাঁর জন্য এক ঠাণ্ডা রক্ত রেখে দিয়েছেন। ভালো, তাকে বলো আমি আর আমার নিজের কেউ নই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏بِبَرَاءَةٌ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَلَمَّا بَلَغَ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏لَا يُبَلِّغُهَا إِلَّا أَنَا أَوْ رَجُلٌ مِنْ أَهْلِ بَيْتِي ‏ ‏فَبَعَثَ بِهَا مَعَ ‏ ‏عَلِيٍّ ‏","","",""],[12738,12738,"","ঈশ্বর মারা যাবেন এবং আমার বাবা মারা যাবেন কিন্তু যখন আমার বাবা মারা যাবেন, তখন তিনি মারা যাবেন । জীবিতদের মূল্য দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ أَيْمَنَ ‏ ‏بَكَتْ لَمَّا ‏ ‏قُبِضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَهَا مَا يُبْكِيكِ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي قَدْ عَلِمْتُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيَمُوتُ وَلَكِنْ إِنَّمَا أَبْكِي عَلَى الْوَحْيِ الَّذِي رُفِعَ عَنَّا ‏","","",""],[12739,12739,"","সেই সময়ে, আমরা আমাদের ভাইবোনদের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَحَكَّهَا بِيَدِهِ ‏","","",""],[12740,12740,"","আমরা বধিরদের কথা বলেছিলাম। আমরা যারা আমাদের ছেলে, তাদের খুঁজে বের করার কথা বলেছিলাম, তিনি বলেন তারা আমাদের সাথে আছেন, একজন মানুষ যিনি আমাদের প্রভু এবং বছর হিসাবে আমাদের শিক্ষা দেন আমার ছেলেকে তার কাছে নিয়ে যাও, তার দাস দাবি করেছে যে, ইনিই হচ্ছেন মা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ابْعَثْ مَعَنَا رَجُلًا يُعَلِّمُنَا كِتَابَ رَبِّنَا وَالسُّنَّةَ قَالَ فَأَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏فَدَفَعَهُ إِلَيْهِمْ وَقَالَ ‏ ‏هَذَا أَمِينُ هَذِهِ الْأُمَّةِ ‏","","",""],[12741,12741,"","আমরা বধিরদের কথা বলেছিলাম। আমরা জানতে পারলাম যে মানুষ ঈশ্বরের কাছে যাচ্ছে কিনা। সে আল্লাহ্‌কে পেয়েছে। আমি তার মাথা ধরে রাখবো, যখন আমার বাবার সবচেয়ে সুন্দর প্রবৃত্তির মধ্যে একটা আঁকা হয়েছিল। সে হঠাৎ করে এটা নিয়ে গেছে, তুমি নিজেই নিজের কাজে লেগেছো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أَرَادَ أَنْ يَحْلِقَ رَأْسَهُ قَبَضَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عَلَى أَحَدِ شِقَّيْ رَأْسِهِ فَلَمَّا حَلَقَهُ ‏ ‏الْحَجَّامُ ‏ ‏أَخَذَهُ فَجَاءَ بِهِ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏فَجَعَلَتْ تَجْعَلُهُ فِي طِيبِهَا ‏","","",""],[12742,12742,"","আমি বলেছিলাম যে, আমরা বধির ব্যক্তিদের সঙ্গে কথা বলেছি এবং যারা ঈশ্বরকে তার বাবা - মার কাছে পাঠিয়েছিলেন, তাদের সম্বন্ধে আমরা অনেক কথা বলেছি । ঋণের অনুগ্রহ এবং শেষ সময়ে আমাদের ঋণের কথা জিজ্ঞেস করা যেতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ كَأَنِّي اللَّيْلَةَ فِي دَارِ ‏ ‏رَافِعِ بْنِ عُقْبَةَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي دَارِ ‏ ‏عُقْبَةَ بْنِ رَافِعٍ ‏ ‏فَأُوتِينَا بِتَمْرٍ مِنْ تَمْرِ ‏ ‏ابْنِ طَابٍ ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ لَنَا الرِّفْعَةَ فِي الدُّنْيَا ‏ ‏وَالْعَاقِبَةَ ‏ ‏فِي الْآخِرَةِ وَأَنَّ دِينَنَا قَدْ طَابَ ‏","","",""],[12743,12743,"","আমি সেই বধির ব্যক্তিদের সম্বন্ধে কথা বলেছিলাম, যারা আমার ছেলেকে একটা বাচ্চাকে দিয়ে আমার ছেলেকে মানুষ করে তোলার বিষয়ে কথা বলেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ أَبِي بَكْرٍ الْمُزَنِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ أَبِي مَيْمُونَةَ ‏ ‏قَالَ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا رُفِعَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْرٌ فِيهِ ‏ ‏الْقِصَاصُ ‏ ‏إِلَّا أَمَرَ فِيهِ بِالْعَفْوِ ‏","","",""],[12744,12744,"","আমরা ঐ বধিরদের কথা বলেছিলাম, আমরা এটা নিয়ে কথা বলেছি, সে তার সাথে কথা বলছিল যখন সে সব কথা বলতো আর তারপর সে আবার সবকিছু পাল্টে দিত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُثَنَّى ‏ ‏عَنْ ‏ ‏ثُمَامَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا تَكَلَّمَ بِكَلِمَةٍ رَدَّدَهَا ثَلَاثًا وَإِذَا أَتَى قَوْمًا فَسَلَّمَ عَلَيْهِمْ سَلَّمَ عَلَيْهِمْ ثَلَاثًا ‏","","",""],[12745,12745,"","আমরা পাথর স্পর্শ করার স্বাধীনতা নিয়ে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার মায়ের গর্বকে খেতে আমার আবেগকে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏بِسْطَامُ بْنُ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ الْحَرَّانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَفَاعَتِي لِأَهْلِ الْكَبَائِرِ مِنْ أُمَّتِي ‏","","",""],[12746,12746,"","আমরা সেই বধিরদের কথা বলেছিলাম, আমরা বাবার স্বপ্নের কথা বলেছিলাম একটা ছোট ছেলে আমাকে ভুলে যাওয়ার কথা ভুলে যাওয়ার কথা। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং একজন নিহত কবির পঞ্চমজন থেকে একটি গোপন তথ্য প্রদান করেছেন, যা হচ্ছে সেই সব বধিরদের কথা প্রথম বার ফোন করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارٌ أَبُو هَاشِمٍ ‏ ‏صَاحِبُ ‏ ‏الزَّعْفَرَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏نَاوَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِسْرَةً ‏ ‏مِنْ خُبْزِ شَعِيرٍ فَقَالَ ‏ ‏هَذَا أَوَّلُ طَعَامٍ أَكَلَهُ أَبُوكِ مِنْ ثَلَاثَةِ أَيَّامٍ ‏","","",""],[12747,12747,"","আমরা সেই বধির শহরের কথা বলেছিলাম, যে দুটো শহর নিয়ে আমরা কথা বলেছি, আমরা মানুষের কথা ভুলে যেতে চাই আমার ভালো লাগবে। ঈশ্বর বলেছেন, তার কাছে তার সবচেয়ে ভালো ঈশ্বরের আছে। তিনি আমাকে বলেছিলেন, আমি কাকে ভালোবাসি তার সাথে কথা বলতে। আর তারপর তিনি বললেন, তিনি আকাশ থেকে কথা শুনতে ভয় পাবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ الْقَطَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَعْرَابِيًّا ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قِيَامِ السَّاعَةِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَعْدَدْتَ لَهَا قَالَ لَا إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ قَالَ وَثَمَّ ‏ ‏غُلَامٌ ‏ ‏فَقَالَ إِنْ يَعِشْ هَذَا فَلَنْ يَبْلُغَ ‏ ‏الْهَرَمَ ‏ ‏حَتَّى تَقُومَ السَّاعَةُ ‏","","",""],[12748,12748,"","ঈশ্বর আমাকে আপনার টাকা দিয়ে আশীর্বাদ করুন কিন্তু, আপনি যদি আপনার সন্তানদের সঙ্গে কথা বলেন, তাহলে আপনি তাদের কথা মনোযোগ দিয়ে শোনেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ بَصْرِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ ‏ ‏عَمْرُو بْنُ زُنَيْبٍ الْعَنْبَرِيُّ ‏ ‏إِنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏مُعَاذًا ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ كَانَ عَلَيْنَا أُمَرَاءُ لَا ‏ ‏يَسْتَنُّونَ ‏ ‏بِسُنَّتِكَ وَلَا يَأْخُذُونَ بِأَمْرِكَ فَمَا تَأْمُرُ فِي أَمْرِهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا طَاعَةَ لِمَنْ لَمْ يُطِعْ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[12749,12749,"","তিনি তাদেরকে খুঁজে পেয়েছিলেন যে, ভাববাদী তার কাছে ও তিনি যা করেছিলেন, তা তিনি দেখতে পেয়েছিলেন । ঈশ্বর তাকে আদেশ দিয়েছেন, সে আমাকে দোষ দিবে না। ভগবান কসম কেটেছি না, আমি বিজয় পাবো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُوسَى بْنَ أَنَسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏الْأَنْصَارَ ‏ ‏اشْتَدَّتْ عَلَيْهِمْ ‏ ‏السَّوَانِي ‏ ‏فَأَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَدْعُوَ لَهُمْ أَوْ يَحْفِرَ لَهُمْ نَهْرًا فَأُخْبِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَقَالَ لَا يَسْأَلُونِي الْيَوْمَ شَيْئًا إِلَّا أُعْطُوهُ فَأُخْبِرَتْ ‏ ‏الْأَنْصَارُ ‏ ‏بِذَلِكَ فَلَمَّا سَمِعُوا مَا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ادْعُ اللَّهَ لَنَا بِالْمَغْفِرَةِ فَقَالَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏","","",""],[12750,12750,"","তিনি বলেছিলেন, তিনি তার দুর্দশার জন্য তোমাদের মধ্যে কাউকে পড়তে দিতে পেরে খুশি হবেন । বিড়াল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ أَنْ يَسْقُطَ عَلَى بَعِيرِهِ وَقَدْ أَضَلَّهُ بِأَرْضٍ ‏ ‏فَلَاةٍ ‏ ‏وَحَدَّثَ ‏ ‏بِذَلِكَ ‏ ‏شَهْرٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[12751,12751,"","আমরা আমার ছেলের কথা বলেছিলাম, সে সবাইকে দোষ দিতে চেয়েছিল, যখন সে মাটিতে পড়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏ثَابِتًا الْبُنَانِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْرِضُ لَهُ الرَّجُلُ يَوْمَ الْجُمُعَةِ بَعْدَمَا يَنْزِلُ مِنْ الْمِنْبَرِ فَيُكَلِّمُهُ ثُمَّ يَدْخُلُ فِي الصَّلَاةِ ‏","","",""],[12752,12752,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম, আমি শুনেছি যে তিনি আমার সঙ্গে কথা বলছেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ هِلَالٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى غُبَارِ مَوْكِبِ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏سَاطِعًا فِي سِكَّةِ ‏ ‏بَنِي غَنْمٍ ‏ ‏حِينَ سَارَ إِلَى ‏ ‏بَنِي قُرَيْظَةَ ‏","","",""],[12753,12753,"","আমরা রাজার সাথে কথা বলেছি, বাবার ছেলে মানে আমি আর কথা বলব না। আমি তার লর্ডশিপ থেকে তার কথা শুনেছি। ঘন্টার পর ঘন্টা থেকে বিজ্ঞানের দৃষ্টি বেড়ে যাওয়ার সুযোগ এবং ফাঁদের আনন্দ প্রদর্শন করা, পুরুষ এমনকি একজন মহিলার দশ ভাগেরও বেশি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَنْبَرٍ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَأُحَدِّثَنَّكُمْ بِحَدِيثٍ لَا يُحَدِّثُكُمُوهُ أَحَدٌ بَعْدِي سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ أَنْ ‏ ‏يُرْفَعَ ‏ ‏الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيُشْرَبَ الْخَمْرُ وَيَظْهَرَ الزِّنَا ‏ ‏وَتَقِلَّ الرِّجَالُ وَيَكْثُرَ النِّسَاءُ حَتَّى يَكُونَ فِي الْخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ ‏","","",""],[12754,12754,"","তিনি সেই ব্যক্তিকে সেই ব্যক্তিকে পানীয় পান করতে দিতে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَشْرَبَ الرَّجُلُ قَائِمًا ‏","","",""],[12755,12755,"","আমরা রাজার জন্মের কথা বলেছিলাম, যারা ঈশ্বরের শান্তি অর্জন করেছে তাদের কথা বলছি, তুমি ইনস্যুরেন্সের হিসাব করছো, আর আমি তোমাকে পুরোপুরি ঝামেলায় ফেলে দিতে পারবো না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَسْجُدْ أَحَدُكُمْ بَاسِطًا ذِرَاعَيْهِ كَالْكَلْبِ ‏","","",""],[12756,12756,"","আমরা রাজার কথা বলেছিলাম যখন তার জন্ম হবে, তখন আমরা রাজার কথা বলেছিলাম । যাও, কাপুরুষের ভেতরে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْعَجْزِ ‏ ‏وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏وَالْبُخْلِ وَالْجُبْنِ ‏","","",""],[12757,12757,"","আমরা রাজার সাথে দেবী হওয়ার কথা বলেছিলাম, আমি তার প্রশংসা করতাম যদি তারা তার হাত আর নাম নিয়ে যেত আর তার পাশে তাকে বসত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏ذَبَحَهُمَا بِيَدِهِ وَسَمَّى وَكَبَّرَ وَوَضَعَ رِجْلَهُ عَلَى ‏ ‏صِفَاحِهِمَا ‏","","",""],[12758,12758,"","আমরা রাজার মাধ্যমে কথা বলেছি যে আমার বাবার ছেলে বিয়ে করতে যাচ্ছে বিয়ে করতে যে ছেলে জন্ম নিয়েছে, সে পাখিকে ফোন করবে আর জীবিতদের স্পর্শ করবে সূর্যয় যাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ حَيَّةٌ ثُمَّ يَذْهَبُ الذَّاهِبُ إِلَى ‏ ‏العَوَالِى ‏ ‏فَيَأْتِيهَا وَالشَّمْسُ مُرْتَفِعَةٌ ‏","","",""],[12759,12759,"","আমরা একটা ছেলের কথা বলেছিলাম, যে আমাদের সাথে এমন একটা ছেলে ছিল, সে এটা করতে গিয়েছিল, আর সে এমন মানুষ ছেড়ে দিত যারা ভয়ানক সময় থেকে প্রার্থনা করত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى نَاسٍ وَهُمْ يُصَلُّونَ قُعُودًا مِنْ مَرَضٍ فَقَالَ ‏ ‏إِنَّ صَلَاةَ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ ‏","","",""],[12760,12760,"","আমরা মূসা সম্পর্কে কথা বলেছি কিন্তু আপনার টাকা ভুলে যান। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন যে আপনি একজন বন্দীকে ছেড়ে চলে যাবেন। তারা বলেছিল, \"ঈশ্বর আমাদের সাথে এবং আমাদের সাথে আছেন।\" তাঁরা বলেছেন, \"ঈশ্বর আমাদের এবং আমাদের সাথে আছেন।\" তারা ঈশ্বরের কাছে যাবে.\"","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ تَرَكْتُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏رِجَالًا مَا سِرْتُمْ مِنْ مَسِيرٍ وَلَا أَنْفَقْتُمْ مِنْ نَفَقَةٍ وَلَا قَطَعْتُمْ مِنْ وَادٍ إِلَّا وَهُمْ مَعَكُمْ فِيهِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَكُونُونَ مَعَنَا وَهُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ ‏ ‏حَبَسَهُمْ ‏ ‏الْعُذْرُ ‏","","",""],[12761,12761,"","আমি এমন একজন ছেলের মতো অনুভব করেছিলাম, যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন বলে মনে হয়, যিনি একজন শাসক থেকে আত্মসমর্পণ হয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏سُئِلَ عَنْ شَعَرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا رَأَيْتُ شَعَرًا أَشَبَهَ بِشَعْرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏قَتَادَةَ ‏ ‏فَفَرِحَ يَوْمَئِذٍ ‏ ‏قَتَادَةُ ‏","","",""],[12762,12762,"","আমরা একটা ছেলে নিয়ে কথা বলেছিলাম যে তার গলা ভেঙ্গে ফেলার চেষ্টা করেছিল. এম. এর সঙ্গে বিকেলে বললেন, তিনি যেতে চান, তারপর তাকে প্রার্থনা করতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏خَارِجَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏مِنْ وَلَدِ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْصَرَفْنَا مِنْ الظُّهْرِ مَعَ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏فَدَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقَالَ يَا ‏ ‏جَارِيَةُ ‏ ‏انْظُرِي هَلْ حَانَتْ قَالَ قَالَتْ نَعَمْ فَقُلْنَا لَهُ إِنَّمَا انْصَرَفْنَا مِنْ الظُّهْرِ الْآنَ مَعَ الْإِمَامِ قَالَ ‏ ‏فَقَامَ فَصَلَّى الْعَصْرَ ثُمَّ قَالَ هَكَذَا كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12763,12763,"","আমরা ইশ্বরের কাছে এত গর্বিত হয়ে কথা বলেছি যে আমরা খুব খুশি হব যারা আমাকে হুমকি দেবে এটা বিশ্বাস করতে যে তিনি হবেন সেই ব্যক্তি, যিনি হবেন। সে-ই হবে সেই লোক যে একজন হবে, সে হবে সেই ব্যক্তি যে হবে হবে সেই ব্যক্তি, যিনি হবেন একজন হবে । সে যদি রাজা হত, তাহলে সে নিশ্চয়ই রাজা হত। ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং জিজ্ঞেস করেছিলেন যে, তিনি কি কখনো তার জন্য প্রার্থনা করবেন? তোমাকে বাঁচিয়েছি, তুমি বলেছিলে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ يَهُودِيًّا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مَعَ أَصْحَابِهِ فَقَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَرَدَّ عَلَيْهِ الْقَوْمُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَا قَالَ قَالُوا نَعَمْ قَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ قَالَ رُدُّوا عَلَيَّ الرَّجُلَ فَرَدُّوهُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتَ كَذَا وَكَذَا قَالَ نَعَمْ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ عَلَيْكُمْ أَحَدٌ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏فَقُولُوا عَلَيْكَ أَيْ عَلَيْكَ مَا قُلْتَ ‏","","",""],[12764,12764,"","আমরা ঈশ্বরের মহিমা নিয়ে কথা বলেছি যখন আমরা প্রভুর মঙ্গলভাব নিয়ে কথা বলেছিলাম। তার সাথে যারা তাকে হত্যা করার চেষ্টা করছে, তাদের সাথে এমন এক পথে, আমি বলি ঈশ্বরও নয়, তুমি এখানে বসে বসে আছো। সে তার প্রয়োজনের আগ পর্যন্ত বসে ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرِيقٍ مَعَهُ نَاسٌ مِنْ أَصْحَابِهِ فَلَقِيَتْهُ امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي إِلَيْكَ حَاجَةً فَقَالَ ‏ ‏يَا أُمَّ فُلَانٍ اجْلِسِي فِي أَيِّ نَوَاحِي السِّكَكِ شِئْتِ أَجْلِسْ إِلَيْكِ فَفَعَلَتْ فَجَلَسَ إِلَيْهَا حَتَّى قَضَتْ حَاجَتَهَا ‏","","",""],[12765,12765,"","আমরা এমন একজন পাগল হয়ে গেছি যে তোমার টাকা ভুলে যাওয়ার স্বপ্ন ভুলে গেছে... ...যে নবী তার জন্য ঈশ্বরের কাছে পৌঁছেছেন, সে তার অধিকার থেকে তাকে ধরে রাখার জন্য। তার বাবা জিজ্ঞেস করেছিলেন, আর তারপর সে আটকে পড়ে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا حَلَقَ بَدَأَ ‏ ‏بِشِقِّ ‏ ‏رَأْسِهِ الْأَيْمَنِ فَحَلَقَهُ ثُمَّ نَاوَلَهُ ‏ ‏أَبَا طَلْحَةَ ‏ ‏قَالَ ثُمَّ حَلَقَ ‏ ‏شِقَّ ‏ ‏رَأْسِهِ الْأَيْسَرَ فَقَسَمَهُ بَيْنَ النَّاسِ ‏","","",""],[12766,12766,"","আমরা সবচেয়ে বড় সংবাদের আশীর্বাদ নিয়ে কথা বলেছি যারা ঈশ্বরের কাছে পাঠানো মানুষের উপর শাসন করতে পেরে আমরা খুশি। তুমি কখনো বেঁচে যাওনি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاتِهِ فَلَا ‏ ‏يَتْفُلْ ‏ ‏أَمَامَهُ وَلَا عَنْ يَمِينِهِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ ‏ ‏وَلْيَتْفُلْ ‏ ‏عَنْ يَسَارِهِ ‏ ‏أَوْ تَحْتَ قَدَمِهِ ‏","","",""],[12767,12767,"","আমরা একটি নির্দিষ্ট গর্বের সাথে কথা বলেছি যা আমাদের বলে দিয়েছে যে আমরা মানুষকে দেখে খুশি হব যে আমার প্রভু এসে পৌঁছেছেন। সে বলেছে আমাদের লোকেরা আছে তুমি তিন শত বার কি বলেছ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِنَاءٍ فِيهِ مَاءٌ قَدْرَ مَا يَغْمُرُ أَصَابِعَهُ ‏ ‏أَوْ لَا يَغْمُرُ أَصَابِعَهُ شَكَّ ‏ ‏سَعِيدٌ ‏ ‏فَجَعَلُوا يَتَوَضَّئُونَ وَالْمَاءُ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ قَالَ قُلْنَا ‏ ‏لِأَنَسٍ ‏ ‏كَمْ كُنْتُمْ قَالَ ثَلَاثَ مِائَةٍ ‏","","",""],[12768,12768,"","আমরা সবচেয়ে বড় সংবাদের আশীর্বাদ নিয়ে কথা বলেছি যারা সবচেয়ে শক্তিশালী মানুষ তাদের উপর শাসন করতে পেরে আমরা খুশি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً ‏","","",""],[12769,12769,"","আমরা দাড়ি নিয়ে কথা বলেছি... ...আমাদের প্রতিশ্রুতি দিতে হবে যে তুমি তোমার নিজের বিচারকের কাছে যাবে. \"তোমার শক্তি থেকে তাকে জীবিত করা এবং তারা আমাকে হতাশ করার জন্য ভুল করেছে। আমি আমাদের সকল ঋণের প্রতি পছন্দ করি,\"ঈশ্বর, আমরা জানি তোমার সাথে কি হচ্ছে। \" তাদের সময় থেকে টেনে নেয়া অপরাধীদের বিচার করার জন্য তারা তাদের সময় থেকে বঞ্চিত হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ ‏} ‏مَرْجِعَهُ مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَهُمْ مُخَالِطُهُمْ الْحُزْنُ وَالْكَآبَةُ وَقَدْ ‏ ‏نَحَرَ ‏ ‏الْهَدْيَ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فَقَالَ لَقَدْ ‏ ‏أُنْزِلَتْ آيَةٌ هِيَ أَحَبُّ إِلَيَّ مِنْ الدُّنْيَا جَمِيعًا قَالُوا يَا رَسُولَ اللَّهِ قَدْ عَلِمْنَا مَا يُفْعَلُ بِكَ فَمَا يُفْعَلُ بِنَا فَأُنْزِلَتْ ‏ { ‏لِيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ ‏ ‏تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَكَانَ ذَلِكَ عِنْدَ اللَّهِ فَوْزًا عَظِيمًا ‏} ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏فِي حَدِيثِهِ وَأَصْحَابُهُ مُخَالِطُو الْحُزْنِ وَالْكَآبَةِ وَقَالَ فِيهِ فَقَالَ قَائِلٌ هَنِيئًا ‏ ‏مَرِيئًا ‏ ‏لَكَ يَا رَسُولَ اللَّهِ قَدْ بَيَّنَ اللَّهُ عَزَّ وَجَلَّ مَاذَا يَفْعَلُ بِكَ ‏","","",""],[12770,12770,"","আমরা দাড়ি নিয়ে কথা বলেছি যে আমরা একটা নিয়মে খুশী হতে বলেছিলাম যে, ভাববাদীকে এটা করতে বলা হয়েছে। আমি আশা করি তার পিছনে যে কাগজগুলো তাকে অনুসরণ করা হয়েছিল সেগুলো তার মধ্যে ছোট ছিল। শেষ সারি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتِمُّوا الصَّفَّ الْأَوَّلَ وَالَّذِي يَلِيهِ فَإِنْ كَانَ نَقْصٌ فَلْيَكُنْ فِي الصَّفِّ الْآخِرِ ‏","","",""],[12771,12771,"","আমরা আপনার টাকার একটি সামান্য গর্বে কথা বলেছি যে আমরা আপনার টাকা ভুলে যেতে পেরে খুশি। আমার একটি ভালো ভাগ্যের জন্য একটি ইঙ্গিত দিতে হবে, একটি ঘুমের সহযাত্রী হিসেবে ভালো সময়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْخَصَ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَالزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏فِي قُمُصٍ مِنْ حَرِيرٍ فِي سَفَرٍ مِنْ ‏ ‏حِكَّةٍ ‏ ‏كَانَتْ بِهِمَا ‏","","",""],[12772,12772,"","আমি আমার ভাইয়ের চেয়ে ভালো একটা কুত্তার ছেলে হওয়ার কথা বলেছিলাম, আমি তোমার টাকা ভুলে গেছি, ঈশ্বর এসে এটা উদ্ধার করতে এসেছেন এবং তা উদ্ধার করতে হবে। \"আশা এবং শ্বাসরুদ্ধকর অবস্থায়।\" চোখ দুটোর চোখ পড়ে ছিল চোখ এবং চোখকে উজ্জ্বল করে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيِّ بْنِ يَزِيدَ ‏ ‏أَخِي ‏ ‏يُونُسَ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَهَا ‏ { ‏وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ ‏ ‏وَالْعَيْنُ ‏ ‏بِالْعَيْنِ ‏} ‏نَصَبَ النَّفْسَ وَرَفَعَ الْعَيْنَ ‏","","",""],[12773,12773,"","আমরা ঈশ্বরের চেয়ে ভালো কথা বলেছি... ...আমাদের সামনে এমন একটা দিন চলে যাওয়ার চেয়ে... ...যে সবসময় লড়াই করে, সে তাকে মেরে ফেলবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏انْطَلَقَ ‏ ‏حَارِثَةُ بْنُ سُرَاقَةَ ‏ ‏نَظَّارًا ‏ ‏مَا انْطَلَقَ لِلْقِتَالِ فَأَصَابَهُ سَهْمٌ فَقَتَلَهُ فَجَاءَتْ ‏ ‏أُمُّهُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ابْنِي ‏ ‏حَارِثَةُ ‏ ‏إِنْ يَكُ فِي الْجَنَّةِ أَصْبِرْ وَأَحْتَسِبْ فَقَالَ يَا ‏ ‏أُمَّ حَارِثَةَ ‏ ‏إِنَّهَا ‏ ‏جِنَانٌ ‏ ‏كَثِيرَةٌ وَإِنَّ ‏ ‏حَارِثَةَ ‏ ‏فِي الْفِرْدَوْسِ الْأَعْلَى ‏","","",""],[12774,12774,"","আমরা ঈশ্বরের কথা বলেছি আমাদের চেয়ে ভাল, তোমার টাকা ভুলে গিয়ে... ...ঈশ্বর তোমাকে যে টাকা দিয়েছেন, তা কে দিয়েছে বলে, ঈশ্বর জিতে দিয়েছেন এবং করেছেন। তার বার্তাবাহক.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أَعْيَنَ الْبَصْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ وَمَنْ تَرَكَ دَيْنًا فَعَلَى اللَّهِ عَزَّ وَجَلَّ وَعَلَى رَسُولِهِ ‏","","",""],[12775,12775,"","আমরা কথা বলেছি কারণ আমরা আপনার টাকা ভুলে খুশি হয়েছি যে, ঈশ্বর ঈশ্বরের ইচ্ছার কাছে পৌঁছেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏وَلِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏فِي لُبْسِ الْحَرِيرِ فِي السَّفَرِ مِنْ ‏ ‏حِكَّةٍ ‏ ‏كَانَتْ بِهِمَا ‏","","",""],[12776,12776,"","আমরা আমার সমর্থকদের কথা বলেছিলাম আমরা কীভাবে আপনাদের কথা শুনছিলাম। ঈশ্বরের দয়া তার ইচ্ছার উপর আছে আর তিনি আবদ্ধ হবেন আর কখনই তা ধরে রাখতে পারবেন না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَجِمُ ‏ ‏وَلَا يَظْلِمُ أَحَدًا أَجْرَهُ ‏","","",""],[12777,12777,"","আমরা একটা ঘোড়ার কথা বলেছি, আমরা তোমার টাকা দিয়ে আমার ফুলকে ভালো সময়ের জন্য নিয়ে কথা বলেছি। ঈশ্বর দাবি করেছেন এবং তার প্রার্থনাগুলো দিয়েছেন, ঈশ্বর কি বলতে চান এবং তারপর তারপর তাকে কি বলতে হবে, আল্লাহ্ কি বলে দিয়েছেন স্প্লিট","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَدَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاصِيَتَهُ مَا شَاءَ اللَّهُ أَنْ يَسْدُلَهَا ثُمَّ ‏ ‏فَرَّقَ ‏ ‏بَعْدُ ‏","","",""],[12778,12778,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং সেই ব্যক্তিদের কাছে তিনি একটা ফোন করেছিলেন, যারা তাকে হত্যা করেছে । কিন্তু আমার ছেলে, খোদা চলে গেছে আর আমরা তোমার মনে পড়ে গেছি, আমরা অসুস্থ।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا عَلَى الَّذِينَ قَتَلُوا أَهْلَ ‏ ‏بِئْرِ مَعُونَةَ ‏ ‏ثَلَاثِينَ صَبَاحًا عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَلِحْيَانَ ‏ ‏وَبَنِي عُصَيَّةَ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ وَنَزَلَ فِي ذَلِكَ قُرْآنٌ فَقَرَأْنَاهُ بَلِّغُوا عَنَّا قَوْمَنَا أَنَّا قَدْ لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا ‏","","",""],[12779,12779,"","সেই শহর হচ্ছে সেই মা, যিনি এটা দেওয়ার জন্য ঈশ্বরের হস্ত নিয়ে নেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَتْ الْخَادِمُ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏وَهِيَ أَمَةٌ تَأْخُذُ بِيَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا يَنْزِعُ يَدَهُ مِنْهَا حَتَّى تَذْهَبَ بِهِ حَيْثُ شَاءَتْ ‏","","",""],[12780,12780,"","তিনি এমনকি তার ভুলকে দেখার জন্য তার হাত বাড়িয়ে দিয়েছিলেন, যখন তিনি আপনাকে কোনো একটা কাজ করার কথা বলেছিলেন । তুমি তাকে বলেছিলে ঈশ্বর যেন হতে যাচ্ছেন","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ فِي الدُّعَاءِ حَتَّى يُرَى بَيَاضُ إِبِطَيْهِ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِعَلِيِّ بْنِ زَيْدٍ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا ذَلِكَ فِي ‏ ‏الِاسْتِسْقَاءِ قَالَ قُلْتُ أَنْتَ سَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ سُبْحَانَ اللَّهِ ‏","","",""],[12781,12781,"","আমরা ঈশ্বরের পুত্রদের কথা বলেছি যারা আমাদের জন্য জীবন দিয়েছে তাদের জন্য, আর এটা তোমার ছেলের জন্য যাত্রা, যাতে তারা ক্ষমা না পায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَهُوَ فِي ‏ ‏رَحْلٍ ‏ ‏لَهُ ‏ ‏لَبَّيْكَ ‏ ‏لَا عَيْشَ إِلَّا عَيْشَ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏تَوَاضُعًا فِي ‏ ‏رَحْلِهِ ‏","","",""],[12782,12782,"","আমরা ঈশ্বরের ছেলেদের নিয়ে অনেক বছর ধরে কথা বলেছি, ঈশ্বরের ইচ্ছা ছিল, ঈশ্বরের ইচ্ছা ছিল, ঈশ্বরের ইচ্ছা ছিল, আমি আমার বাবাকে বদলে দিবো এবং তারা তা পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏لَا يَقْرَءُونَ ‏ ‏يَعْنِي لَا يَجْهَرُونَ ‏","","",""],[12783,12783,"","আমরা ঈশ্বরের পুত্রদের কথা বলেছি, যারা শেষ চ্যাম্পিয়ন হবার কথা বলছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাকে এক একগুঁয়ে ঠাণ্ডায় নিয়ে যান।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏آخِرُ صَلَاةٍ صَلَّاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِ ‏ ‏بُرْدٌ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ وَهُوَ قَاعِدٌ ‏","","",""],[12784,12784,"","আমরা শপথ নিয়ে কথা বলেছিলাম যে সে আমাদের সাথে কথা বলবে, সে এমন কিছু বলবে যেন আমাকে ঋণ নিতে হবে অথবা কিছু করতে হবে। সে যাওয়ার পর সে বলল, সে ভয় নিয়ে সন্দেহের মধ্যে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ مَا بَيْنَ نَاحِيَتَيْ حَوْضِي مَثَلُ مَا بَيْنَ ‏ ‏صَنْعَاءَ ‏ ‏وَالْمَدِينَةِ ‏ ‏أَوْ مَثَلُ مَا بَيْنَ ‏ ‏الْمَدِينَةِ ‏ ‏وَعَمَّانَ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏شَكَّ ‏ ‏هِشَامٌ ‏","","",""],[12785,12785,"","আমরা তোমার টাকা ভুলে যেতে বলেছিলাম, সে তোমার কথা ভুলে যাবে, আমি তাকে ছেড়ে দেব, যে প্রার্থনা বন্ধ করবে, না হলে সে তাকে হারবে।","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يَرْقُدُ عَنْ الصَّلَاةِ أَوْ يَغْفُلُ عَنْهَا قَالَ لِيُصَلِّهَا إِذَا ذَكَرَهَا ‏","","",""],[12786,12786,"","আমরা এমন একটা নিয়ম সম্বন্ধে কথা বলেছিলাম, যার সম্বন্ধে আরও বেশি ঈশ্বরকে জিজ্ঞেস করা প্রয়োজন । সে খুব কোমল ছিল.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ ‏ ‏يَخْضِبْ ‏ ‏قَطُّ إِنَّمَا كَانَ الْبَيَاضُ فِي مُقَدَّمِ لِحْيَتِهِ وَفِي ‏ ‏الْعَنْفَقَةِ ‏ ‏وَفِي الرَّأْسِ وَفِي ‏ ‏الصُّدْغَيْنِ ‏ ‏شَيْئًا لَا يَكَادُ يُرَى ‏ ‏وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَضَبَ ‏ ‏بِالْحِنَّاءِ ‏","","",""],[12787,12787,"","আমরা বাবা কথা বলেছিলাম আমার ভাই কিভাবে চলে গেছে তা নিয়ে কথা বলতে। আপনার টাকা নিয়ে একটা বাপ্তিস্ম নিয়ে তিনি বলেছিলেন যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন আর তিনি মানুষকে ছেড়ে দিতে চান। তার কাছে থাকতে হবে, ঈশ্বরের কাছে প্রার্থনা করব, আর তিনি আমাদের সবচেয়ে ভালোটা দেবেন, আমরা বলবো যে আমরা যখন তার মত হব না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ مَعْبَدٍ ‏ ‏ابْنُ أَخِي ‏ ‏حُمَيْدِ بْنِ عَبْدِ اللَّهِ الْحِمْيَرِيِّ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ مَعَ ‏ ‏حُمَيْدٍ ‏ ‏إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَايَعَهُ النَّاسُ ‏ ‏أَوْ كُنَّا إِذَا بَايَعْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَقِّنُنَا أَنْ يَقُولَ لَنَا فِيمَا اسْتَطَعْتَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَيْسَ هُوَ ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏","","",""],[12788,12788,"","আমরা তোমার টাকা দিয়ে শাসন করার চেষ্টা করেছি, বাল্বের জন্য তাকে এক মাস সময় দেওয়া হয়েছে আর আমার ছেলে চোরও।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَنَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏عَصَوْا اللَّهَ وَرَسُولَهُ ‏","","",""],[12789,12789,"","আমরা এমন এক প্যাকেট নিয়ে কথা বলেছি, যেটা আমরা ভাল করে শুনেছি সে বেরিয়ে আসবে এবং তার অভিজ্ঞতার কিছু অভিজ্ঞতা নিয়ে বের হয়ে আসবে এবং সে মানুষ পেয়ে যাবে যারা তার চুরি করতে চায় তারা বলে, \"ঈশ্বর, আমরা কখনোই খুঁজে পাইনি যে আমরা তোমার ভালোবাসার মুখে ছিলাম\" একটা জল বয়ে যাচ্ছে, আমার ছেলের দয়া দেয়া হয়েছে তার আত্মা, তাকে উদ্ধার করার সুযোগ দেওয়া হয়েছে, তারপর সে বলেছিল যে তারা যদি যেতে চায় তাহলে আলো জ্বালিয়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَزْمٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ذَاتَ يَوْمٍ لِبَعْضِ مَخَارِجِهِ وَمَعَهُ نَاسٌ مِنْ أَصْحَابِهِ فَانْطَلَقُوا يَسِيرُونَ فَحَضَرَتْ الصَّلَاةُ فَلَمْ يَجِدْ الْقَوْمُ مَاءً يَتَوَضَّئُونَ بِهِ فَقَالُوا يَا رَسُولَ اللَّهِ وَاللَّهِ مَا نَجِدُ مَا نَتَوَضَّأُ بِهِ وَرَأَى فِي وُجُوهِ أَصْحَابِهِ كَرَاهِيَةَ ذَلِكَ فَانْطَلَقَ رَجُلٌ مِنْ الْقَوْمِ ‏ ‏فَجَاءَ ‏ ‏بِقَدَحٍ ‏ ‏مِنْ مَاءٍ يَسِيرٍ فَأَخَذَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ مِنْهُ ثُمَّ مَدَّ أَصَابِعَهُ الْأَرْبَعَةَ عَلَى ‏ ‏الْقَدَحِ ‏ ‏ثُمَّ قَالَ هَلُمُّوا فَتَوَضَّئُوا فَتَوَضَّأَ الْقَوْمُ حَتَّى أَبْلَغُوا فِيمَا يُرِيدُونَ قَالَ سُئِلَ كَمْ بَلَغُوا قَالَ سَبْعِينَ ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏","","",""],[12790,12790,"","আমরা বাবার সাথে কথা বলেছিলাম যে আমি করেছি, তার সিঁড়ি আছে আর লোকে বলে যে তুমি তার চোখের সাথে ডেটিং করছ.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏قَلَّ لَيْلَةٌ تَأْتِي عَلَيَّ إِلَّا وَأَنَا أَرَى فِيهَا ‏ ‏خَلِيلِي ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَأَنَسٌ ‏ ‏يَقُولُ ذَلِكَ وَتَدْمَعُ عَيْنَاهُ ‏","","",""],[12791,12791,"","আমরা বাবা আমার সম্বন্ধে জানার চেষ্টা করে বাবার সঙ্গে কথা বলেছিলাম যে, আমার বাবা আমার সম্বন্ধে জানার চেষ্টা করেছিলেন । এই জঙ্গল থেকে সরিয়ে, ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি তাকে ছেড়ে দিবেন। তিনি যখন তাদের বললেন, \"উঠ\" বললে তিনি তাদের ছেড়ে দিবেন। তিনি হয়তো বলতে পারেন যে আমাদের কত প্রয়োজন আছে। আমি জানি, আমি কি করতে পারি, আমি কি করতে পারি? আমি জানি, আমি জানি, আমি কি করতে পারি, আমি এটা করতে পারি। আমি জানি না যে, আমি জানি, আমি এটা করতে পারি। আমি যদি আমি সত্যিই জানি, আমি এটা করতে পারি, আমি সত্যিই অনেক কিছু করতে পারি। আমি জানি, আমি জানি, আমি জানি যে, আমি এটা করতে চাই। আমি জানি না। আমি জানি, আমি জানি, আমি কি করতে পারি। আমি এটা আমার জন্য অনেক কিছু করতে পারি। আমি যদি আমি এটা করতে পারি, আমি এটা করতে পারি, আমি জানি না যে, আমি জানি যে, আমি এটা করতে চাই। আমি এটা আমার জন্য অনেক কিছু একটা জিনিস। আমি যদি আমি চাই, আমি চাই, আমি এটা আমার বাবা না। আমি জানি যে, আমি জানি, আমি এটা করতে পারি, আমি জানি যে, আমি এটা আমার বাবা জানি না। তারা বলে, ঈশ্বর আমাকে ক্ষমা করেছেন, পুত্র পুত্র পুত্র, পুত্র - পুত্রগণ আমাকে বলেন, আমি যেন তাঁকে না বলি । প্রভু, প্রভু এবং প্রভু, আমরা আমাদের মধ্যে সর্বোত্তম বলতে পারি এবং যদি আমরা বলি যে আমার ছেলে শিকারী। সে বলত, আমার মা ঈশ্বরের মায়ের কথা বলেছে। আমি তার কাছে প্রার্থনা করছি। আর সে এরকম ভাবে আত্মসমর্পণ করবে যে সে চোখে বেড়ে গেছে... ...কিন্তু সে অন্ধকারে আছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَدَّادٌ أَبُو طَلْحَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏أَتَتْ ‏ ‏الْأَنْصَارُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجَمَاعَتِهِمْ فَقَالُوا إِلَى مَتَى نَنْزَعُ مِنْ هَذِهِ الْآبَارِ فَلَوْ أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا اللَّهَ لَنَا فَفَجَّرَ لَنَا مِنْ هَذِهِ الْجِبَالِ عُيُونًا فَجَاءُوا بِجَمَاعَتِهِمْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَآهُمْ قَالَ مَرْحَبًا وَأَهْلًا لَقَدْ جَاءَ بِكُمْ إِلَيْنَا حَاجَةٌ قَالُوا إِي وَاللَّهِ يَا رَسُولَ اللَّهِ فَقَالَ إِنَّكُمْ لَنْ تَسْأَلُونِي الْيَوْمَ شَيْئًا إِلَّا أُوتِيتُمُوهُ وَلَا أَسْأَلُ اللَّهَ شَيْئًا إِلَّا أَعْطَانِيهِ فَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ فَقَالُوا الدُّنْيَا تُرِيدُونَ فَاطْلُبُوا الْآخِرَةَ ‏ ‏فَقَالُوا بِجَمَاعَتِهِمْ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ لَنَا أَنْ يَغْفِرَ لَنَا فَقَالَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَأَوْلَادِنَا مِنْ غَيْرِنَا قَالَ وَأَوْلَادِ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏وَمَوَالِينَا ‏ ‏قَالَ ‏ ‏وَمَوَالِي ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏وَحَدَّثَتْنِي ‏ ‏أُمِّي ‏ ‏عَنْ ‏ ‏أُمِّ الْحَكَمِ بِنْتِ النُّعْمَانِ بْنِ صُهْبَانَ ‏ ‏أَنَّهَا سَمِعَتْ ‏ ‏أَنَسًا ‏ ‏يَقُولُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ هَذَا غَيْرَ أَنَّهُ زَادَ فِيهِ ‏ ‏وَكَنَائِنِ ‏ ‏الْأَنْصَارِ ‏","","",""],[12792,12792,"","আমরা দুজন মাস্টারের সাথে কথা বলেছি যে আমরা একজন যুবকের দাম পরিবর্তন করতে যাচ্ছি যে আমাকে যেতে বলেছে, ঈশ্বর তাকে আত্মসমর্পণ করে আমার মা আর চাচার কাছে পেশ করে দিতে হবে। তারা বলে যে, গুয়েরেতে প্রার্থনা করার সময় তারা প্রার্থনা করত, যে - ব্যক্তি বলে -- ''সে নিশ্চয়ই এক ব্যক্তি হতো, সে হবে এক ব্যক্তি, আর সে হবে সেই ব্যক্তি, যে হবে হবে হবে সেই ব্যক্তি।’’ সে-ই হবে সেই ব্যক্তি যে হবে হবে, সে হবে একজন যে হবে হবে সেই হবে, সে হবে একজন যে হবে। সে-ই হবে সেই লোক যে একজন হবে, সে হবে সেই ব্যক্তি যে হবে । সে-ই হবে সেই ব্যক্তি যে হবে সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন একজন হবে সেই ব্যক্তি । সে ব ্ যতীত যে ব ্ যক ্ তি তার পালনকর ্ তার আদেশ পালন করবে , তাকে ছাড়া আর কেউ সাহেব বলে ? আমি তোমাদের সাহেবের সাহেব সাহেবের সাহেব রাজা হিসেবে আমরা রাজা হিসেবে পরিচিত হতে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا وَأُمِّي وَخَالَتِي فَقَالَ ‏ ‏قُومُوا أُصَلِّي بِكُمْ فِي غَيْرِ حِينِ صَلَاةٍ قَالَ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ ‏ ‏لِثَابِتٍ ‏ ‏أَيْنَ جَعَلَ ‏ ‏أَنَسًا ‏ ‏مِنْهُ قَالَ عَلَى يَمِينِهِ وَالنِّسْوَةَ خَلْفَهُ ‏","","",""],[12793,12793,"","মা'কে সাহায্য করার কথা আমার মা বলেছিলেন যে আমি তোমার কথা শুনতে পাচ্ছি। আমার বাবা মারা যান। আমার বাবা তার মহৎ কাজের জন্য এখানে এসেছিলেন এবং তার কাজ সম্পাদন করেছিলেন। আমার বাবা আমার মায়ের উত্তরদাতা হিসেবে। তারা জানতো Dek এবং তার হাত কিনে নিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ يَحْيَى ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَاتَ ابْنٌ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏فَصَلَّى عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُمُّ سُلَيْمٍ ‏ ‏خَلْفَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏كَأَنَّهُمْ عُرْفُ دِيكٍ وَأَشَارَ بِيَدِهِ ‏","","",""],[12794,12794,"","আমরা ব্রেসলেটের কথা বলেছিলাম একটা বাচ্চা থাকার কথা। ঈশ্বরের কাছে আছে এবং আমি তার সাথে আমার রক্তের মা আমাকে বিশ্বাস করাতে বাধ্য করেছে এবং আমার শান্তিই আমাদের শান্তি। একা.","‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ بْنُ سَوَّارٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ ‏ ‏وَأُمُّ سُلَيْمٍ ‏ ‏فَجَعَلَنِي عَنْ يَمِينِهِ ‏ ‏وَأُمَّ سُلَيْمٍ ‏ ‏مِنْ خَلْفِنَا ‏","","",""],[12795,12795,"","আমরা আমার বাবার এক ছেলের ছেলের কথা বলেছিলাম, একটা ছেলে তার ছেলের সাথে কথা বলেছি যে বলল সে ঈশ্বরের কাছে যাবে। সে প্রার্থনা করবে এবং তার স্পর্শ করবে। তারপর বেঁচে গেলাম এবং তারপর... ...বে-বি-বিড়ালের কাছে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ ‏ ‏حَيَّةٌ ‏ ‏ثُمَّ يَذْهَبُ الذَّاهِبُ إِلَى ‏ ‏الْعَوَالِي ‏ ‏فَيَأْتِيهَا وَالشَّمْسُ مُرْتَفِعَةٌ ‏","","",""],[12796,12796,"","আমরা বাবার সাথে ঈশ্বরের দয়া নিয়ে কথা বলেছি, ঈশ্বর তার শান্তির জন্য এসেছেন, আমি তাকে দেখে অবাক হয়ে গেছি যে প্রথম প্রশ্নটা হচ্ছে আমার বাবার শ্বশুরের।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّبْرُ عِنْدَ الصَّدْمَةِ ‏ ‏أُرَاهُ قَالَ الْأُولَى شَكَّ ‏ ‏أَبُو قَطَنٍ ‏","","",""],[12797,12797,"","যুদ্ধের কিছু এলাকার জন্য হাঁটু গেড়ে বসে যুদ্ধের জন্য প্রার্থনা করে পরে আমরা সেই যাজকের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ يَدْعُو عَلَى أَحْيَاءٍ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَرَكَهُ ‏","","",""],[12798,12798,"","আমরা সবচেয়ে ভালো মানুষ সম্পর্কে কথা বলেছি আমরা ক্যাম্পকে বলেছিলাম, আমি চুরি করবো, কিন্তু আমি মানুষ খুন করব তাদের মত করে। যে মানুষ দরজার মাঝখানে যেতে হয়েছে, সে আমাকে টাকা দিচ্ছে মুখ বন্ধ রাখার জন্য, ঈশ্বর তার মৃত্যু কামনা করেছেন তার সেবা করার জন্য। ঈশ্বর খেমারের নামে মানুষকে উদ্ধার করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَقَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا حُرِّمَتْ الْخَمْرُ قَالَ إِنِّي يَوْمَئِذٍ ‏ ‏لَأَسْقِيهِمْ ‏ ‏لَأَسْقِي أَحَدَ عَشَرَ رَجُلًا فَأَمَرُونِي فَكَفَأْتُهَا وَكَفَأَ النَّاسُ آنِيَتَهُمْ بِمَا فِيهَا حَتَّى كَادَتْ السِّكَكُ أَنْ تُمْتَنَعَ مِنْ رِيحِهَا ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَمَا خَمْرُهُمْ يَوْمَئِذٍ إِلَّا ‏ ‏الْبُسْرُ ‏ ‏وَالتَّمْرُ مَخْلُوطَيْنِ ‏ ‏قَالَ فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ كَانَ عِنْدِي مَالُ يَتِيمٍ فَاشْتَرَيْتُ بِهِ خَمْرًا أَفَتَأْذَنُ لِي أَنْ أَبِيعَهُ فَأَرُدَّ عَلَى الْيَتِيمِ مَالَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏حُرِّمَتْ عَلَيْهِمْ ‏ ‏الثُّرُوبُ ‏ ‏فَبَاعُوهَا وَأَكَلُوا أَثْمَانَهَا وَلَمْ يَأْذَنْ لَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْعِ الْخَمْرِ ‏","","",""],[12799,12799,"","আমরা বলতে চাই যে আমরা সেই লোকদের উপর শাসন করতে পেরে খুশি হব যারা আমাদের সাথে যুদ্ধ করতে পারবে না, সে হয়ত তার মজা উপভোগ করবে। হার মানে আমি তাকে খুন করতে চাচ্ছি, যে কারণে সে তৈরি হয়েছে, ঈশ্বর তার দু'টো শব্দ শুনে লজ্জিত যে সে তার গলা উপভোগ করবে এবং তাকে ঈশ্বরের কাছে ডাকতে পারবে। ঈশ্বর আমি আর আমি তার সাথে প্রেম করি না। সে হতাশ হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَبْتَاعُ وَكَانَ فِي ‏ ‏عُقْدَتِهِ ‏ ‏يَعْنِي عَقْلَهُ ‏ ‏ضَعْفٌ فَأَتَى أَهْلُهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا نَبِيَّ اللَّهِ ‏ ‏احْجُرْ ‏ ‏عَلَى فُلَانٍ فَإِنَّهُ يَبْتَاعُ وَفِي ‏ ‏عُقْدَتِهِ ‏ ‏ضَعْفٌ فَدَعَاهُ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَهَاهُ عَنْ الْبَيْعِ فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي لَا أَصْبِرُ عَنْ الْبَيْعِ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كُنْتَ غَيْرَ تَارِكٍ الْبَيْعَ فَقُلْ هُوَ هَا وَلَا ‏ ‏خِلَابَةَ ‏ ‏وَلَا هَا لَا ‏ ‏خِلَابَةَ ‏","","",""],[12800,12800,"","আমরা মাস্টারের ব্যাপারে কথা বলেছি কিন্তু আমি অল্প সময়ের জন্য জিজ্ঞাসা করব, আমি ভগবানকে প্রার্থনা করতে দেখলাম, আর সে তার অধিকার ছেড়ে দিত।","‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الرُّؤَاسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ ‏ ‏الِانْصِرَافِ فَقَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْصَرِفُ عَنْ يَمِينِهِ ‏","","",""]];
